	private $usuarioPreAuth1 = 9;
	private $usuarioPreAuth2 = 82;

	public $condicao_de_pagamento_usar_credito = [4202, 4221, 4247];

	public function index(Request $request)
	{
		if (Auth::user()->hasPermissionTo("programas App\AprovacaoDePedido") === false) {
			return abort(403);
		}
		$request->session()->flash('model', 'App\AprovacaoDePedido');

		$users = UserController::varreSubordinados(Auth::id());
		$representantes = [];

		foreach ($users as $value) {
			$user_info = User::find($value);
			if (empty($user_info->codigo_representante)) {
				continue;
			}
			$representantes += [$value => $user_info->codigo_representante . " - " . $user_info->name];
		}
		$estabelecimentos = returnEmpresasNasajonView();
		unset($estabelecimentos[0]);

		if (Auth::user()->username == 'nelson.namura') {
			unset($estabelecimentos[3]);
			unset($estabelecimentos[4]);
		}

		$status = [
			'credito' => 'Crédito',
			'preco' => 'Preço',
			'retaguarda' => 'Retaguarda'
		];

		return view('programs.aprovacao_pedido.index')->with(['status' => $status, 'estabelecimentos' => $estabelecimentos]);
	}

	public function filter(Request $request)
	{
		$fields = $request->only(['estabelecimento', 'cliente_nome', 'status']);

		$estabelecimento = returnEmpresasNasajonView();

		$users = [];

		$pedidoQuery = AprovacaoDePedido::with(['nivelaprovacao', 'nivelaprovacaoPreco', 'pedido', 'pedido.cliente', 'pedido.condicao_pagamento_detalhes', 'pedido.status_pedido_detalhes', 'pedido.valor_total', 'pedido.usuario_detalhes', 'pedido.usuario_detalhes.tipo_usuario', 'aprovador_credito', 'aprovador_preco', 'aprovadorPre1', 'aprovadorPre2']);
		if (
			strtolower(Auth::user()->tipo_usuario->nome) === "diretor" ||
			strtolower(Auth::user()->tipo_usuario->nome) === "credito"
		) {
		} else if (
			strpos(strtolower(Auth::user()->tipo_usuario->nome), "diretor") !== false ||
			strpos(strtolower(Auth::user()->tipo_usuario->nome), "gerente") !== false
		) {
			$users = UserController::varreSubordinados(Auth::id());
			$pedidoQuery->with(['pedido' => function ($query) use ($users) {
				$query->whereIn('usuario', $users);
			}]);
		} else if (strtolower(Auth::user()->tipo_usuario->nome) === "supervisor" || in_array(Auth::user()->detalhesModelHasRoles->detalhesRoles->name, ['Supervisor Comercial'])) {
			$users = UserController::varreSubordinados(Auth::user()->responsavel);
			$pedidoQuery->with(['pedido' => function ($query) use ($users) {
				$query->whereIn('usuario', $users);
			}]);
		}

		$pedidoQuery->whereHas('pedido', function ($query) use ($fields) {
			$query->whereNotIn('status_pedido', [3, 8, 9, 7]);

			if (Auth::user()->username == 'nelson.namura') {
				$query->whereIn('estabelecimento', [1, 2, 7, 8]);
			}

			if (!is_null($fields['estabelecimento'])) {
				$query->where("estabelecimento", intval($fields['estabelecimento']));
			}
			if (isset($fields['cliente_nome']) && !empty($fields['cliente_nome'])) {
				$query->where(function ($query) use ($fields) {
					$cliente_busca = ClienteNasajon::select('codigo')->where(DB::raw('CONCAT(TRIM(nome),\' - \', cpf_cnpj)'), 'ILIKE', $fields['cliente_nome'])->where('bloqueado', 'false')->get();
					$query->orWhereIn('cod_cliente', $cliente_busca->pluck('codigo'));
				});
			}
		});

		if (!empty($fields['status'])) {
			if ($fields['status'] === 'credito') {
				$pedidoQuery->where('credito', true)
					->whereNull('aprovacao_credito_user_id');
			}
			if ($fields['status'] === 'preco') {
				$pedidoQuery->where('preco', true)
					->whereNull('aprovacao_preco_user_id');
			}
			if ($fields['status'] === 'retaguarda') {
				$pedidoQuery->where('retaguarda', true);
			}
		}
		$pedidos = $pedidoQuery->get();

		$total = ['pedidos' => 0, 'valor' => 0.0];

		$response = [];
		$nivel_usuario = Auth::user()->tipo_usuario->nivel;
		if (in_array(Auth::id(), [91, 120])) {
			$nivel_usuario = 1;
		} else if (in_array(Auth::user()->tipo_usuario_id, [13]) && !in_array(Auth::user()->detalhesModelHasRoles->detalhesRoles->name, ['Gerencia Comercial'])) {
			$nivel_usuario = 2;
		}

		foreach ($pedidos as $pedido) {
			$mostrar_botao_aprovar = false;
			$mostrar_botao_reprovar = false;
			if (is_null($pedido->pedido)) {
				continue;
			}
			$aprovador = $pedido->nivelaprovacao->descricao;
			$condicao_pagamento = ($pedido->pedido->condicao_pagamento_detalhes->descricao) ?? '';
			if (
				$pedido->credito === true
			) {
				if (empty($pedido->aprovacao_credito_user_id)) {
					if (
						empty($pedido->aprovacao_credito_user_id) &&
						strtolower(Auth::user()->tipo_usuario->nome) === 'credito'
					) {
						$mostrar_botao_aprovar = true;
						$mostrar_botao_reprovar = true;
					} else if (
						in_array($pedido->pedido->usuario_detalhes->id, $users) ||
						in_array(strtolower(Auth::user()->tipo_usuario->nome), ['diretor', 'diretor comercial'])
					) {
						$mostrar_botao_reprovar = true;
					}

					if (
						$pedido->preco === true &&
						empty($pedido->aprovacao_preco_user_id) &&
						$nivel_usuario <= $pedido->nivelaprovacaoPreco->id
					) {
						$mostrar_botao_aprovar = true;
						$mostrar_botao_reprovar = true;
					}
				} else {
					if (
						$pedido->preco === true &&
						empty($pedido->aprovacao_preco_user_id) &&
						$nivel_usuario <= $pedido->nivelaprovacaoPreco->id
					) {
						$mostrar_botao_aprovar = true;
						$mostrar_botao_reprovar = true;
					} else if (in_array($pedido->pedido->usuario_detalhes->id, $users)) {
						$mostrar_botao_reprovar = true;
					}
				}
				if (
					$pedido->preco === true
				) {
					if (!empty($pedido->aprovacao_preco_user_id)) {
						$aprovador = '';
					} else {
						$aprovador = $pedido->nivelaprovacaoPreco->descricao;
					}
				} else {
					$aprovador = '';
				}

				if (empty($pedido->aprovacao_credito_user_id)) {
					$aprovador .= (!empty($aprovador) ? ' / ' : '') . 'crédito';
				}
				if ($pedido->pedido_pre == true) {
					if (
						empty($pedido->user_aprovacao_pre_1auth) ||
						empty($pedido->user_aprovacao_pre_2auth)
					) {
						$aprovador .= (!empty($aprovador) ? ' / ' : '') . 'Pré pago';
					}

					if (
						empty($pedido->user_aprovacao_pre_1auth) ||
						empty($pedido->user_aprovacao_pre_2auth)
					) {
						if (
							Auth::id() == $this->usuarioPreAuth1 ||
							Auth::id() == $this->usuarioPreAuth2
						) {
							if (
								!empty($pedido->user_aprovacao_pre_1auth) &&
								$pedido->user_aprovacao_pre_1auth !== Auth::id()
							) {
								if (
									empty($pedido->user_aprovacao_pre_2auth)
								) {
									$mostrar_botao_aprovar = true;
									$mostrar_botao_reprovar = true;
								}
							} else {
								$mostrar_botao_aprovar = true;
								$mostrar_botao_reprovar = true;
							}
						}
					}
				}
			} else {
				if ($nivel_usuario <= $pedido->nivelaprovacao['id']) {
					$mostrar_botao_aprovar = true;
					$mostrar_botao_reprovar = true;
				} else if (in_array($pedido->pedido->usuario_detalhes->id, $users)) {
					$mostrar_botao_reprovar = true;
				}
				if (!empty($pedido->aprovacao_preco_user_id)) {
					$mostrar_botao_aprovar = false;
				}
			}

			if ($pedido->retaguarda == true) {
				if (
					empty($pedido->user_aprovacao_pre_1auth) ||
					empty($pedido->user_aprovacao_pre_2auth)
				) {
					if (
						Auth::id() == $this->usuarioPreAuth1 ||
						Auth::id() == $this->usuarioPreAuth2
					) {
						if (
							!empty($pedido->user_aprovacao_pre_1auth) &&
							$pedido->user_aprovacao_pre_1auth !== Auth::id()
						) {
							if (
								empty($pedido->user_aprovacao_pre_2auth)
							) {
								$mostrar_botao_aprovar = true;
								$mostrar_botao_reprovar = true;
							}
						} else if (empty($pedido->user_aprovacao_pre_1auth)) {
							$mostrar_botao_aprovar = true;
							$mostrar_botao_reprovar = true;
						} else {
							$mostrar_botao_aprovar = false;
						}
					}
				}
			}


			if (strtolower(Auth::user()->tipo_usuario->nome) == 'administrador') {
				$mostrar_botao_aprovar = true;
				$mostrar_botao_reprovar = true;
			}
			if (isset($pedido->pedido)) {
				$total['pedidos']++;

				$total['valor'] += empty($pedido->pedido->valor_total) ? 0 : $pedido->pedido->valor_total->total;

				$tipo_pedido = '';
				$cliente = "";
				if (!empty($pedido->pedido->cliente)) {
					$cliente = "<div><div data-toggle='tooltip' data-html='true' title='' data-original-title='" . ($pedido->pedido->cliente->nome) . "''>" . ($pedido->pedido->cliente->nome) . "</div></div>";
				} else {
					$cliente = "<div><div data-toggle='tooltip' data-html='true' title='' data-original-title='" . ($pedido->pedido->cod_cliente) . "''>" . ($pedido->pedido->cod_cliente) . "</div></div>";
					$mostrar_botao_aprovar = false;
				}
				if (boolval($pedido->pedido->pedido_futuro) == true) {
					$tipo_pedido = 'P F';
				} else {
					$tipo_pedido = 'P E';
				}

				$response[] = [
					'id' => $pedido->id,
					'estabelecimento' => "<div><div data-toggle='tooltip' data-html='true' title='' data-original-title='" . $estabelecimento[$pedido->pedido['estabelecimento']] . "''>" . $estabelecimento[$pedido->pedido['estabelecimento']] . "</div></div>",
					'status' => $aprovador,
					'cliente' => $cliente,
					'pedido' => $pedido->pedido['id'],
					'valor' => empty($pedido->pedido->valor_total) ? '' : parserValor($pedido->pedido->valor_total->total),
					'condicao_pagamento' => "<div><div data-toggle='tooltip' data-html='true' title='' data-original-title='" . $condicao_pagamento . "''>" . $condicao_pagamento . "</div></div>",
					'tipo_pedido' => $tipo_pedido,
					'vendedor' => "<div><div data-toggle='tooltip' data-html='true' title='' data-original-title='" . $pedido->pedido->usuario_detalhes->codigo_representante . " - " . $pedido->pedido->usuario_detalhes->name . "'>" . $pedido->pedido->usuario_detalhes->codigo_representante . " - " . $pedido->pedido->usuario_detalhes->name . "</div></div>",
					'criterio_credito' => $pedido->credito ? (empty($pedido->aprovacao_credito_user_id) ? 'Não' : 'Aprovado') : 'Sim',
					'criterio_preco' => $pedido->preco ? (empty($pedido->aprovacao_preco_user_id) ? 'Não' : 'Aprovado') : 'Sim',
					'mostrar_botao_aprovar' => $mostrar_botao_aprovar,
					'mostrar_botao_reprovar' => $mostrar_botao_reprovar,
					'aprovador_credito' => $pedido->aprovador_credito->name ?? '',
					'aprovador_preco' => $pedido->aprovador_preco->name ?? '',
					'tipo' => 'pedido',
					'data' => parserData($pedido->pedido->data_pedido),

					'retaguarda' => $pedido->retaguarda ? 'Não' : 'Sim',
					'retaguarda1' => $pedido->retaguarda == true && empty($pedido->user_aprovacao_pre_1auth) ? 'Não' : 'Aprovado',
					'retaguarda2' => $pedido->retaguarda == true && empty($pedido->user_aprovacao_pre_2auth) ? 'Não' : 'Aprovado',
					'user_retaguarda1' => $pedido->retaguarda == true && !empty($pedido->aprovadorPre1) ? $pedido->aprovadorPre1->name : '',
					'user_retaguarda2' => $pedido->retaguarda == true && !empty($pedido->aprovadorPre2) ? $pedido->aprovadorPre2->name : '',

				];
			}
		}
		if (Auth::user()->username != 'nelson.namura') {
			$response = $this->filterAprovacaoProjeto($response, $users, $fields, $estabelecimento);

			$total['pedidos'] = $total['pedidos'] + $response['quantidade'];
			$total['valor'] = $total['valor'] + $response['valor_total'];
			unset($response['quantidade']);
			unset($response['valor_total']);
		}

		$total = [
			'pedidos' => $total['pedidos'],
			'valor' => $total['valor'] > 0 ? \parserValor($total['valor']) : ''
		];
		$return = [
			'status' => 'success',
			'message' => '',
			'error' => [],
			'response' => [
				'pedidos' => $response,
				'total' => $total
			]
		];
		return response()->json($return);
	}

	public function checkPedido()
	{
		if (!empty($this->pedido)) {
			if (PedidoPortal::find($this->pedido)) {
				return true;
			} else {
				return false;
			}
		} else {
			return false;
		}
	}

	private function checkPedidoMonitorar(PedidoPortal $Pedido)
	{
		$codigo_transportador_retira = '0001';
		if (intval($codigo_transportador_retira) === intval($Pedido->transportadora)) {
			$PedidosMonitoradoObj = PedidosMonitorado::where('pedido', $Pedido->id)->first();
			if (is_null($PedidosMonitoradoObj)) {
				$PedidosMonitoradoObj = new PedidosMonitorado();
			}
			$PedidosMonitoradoObj->estabelecimento = $Pedido->estabelecimento;
			$PedidosMonitoradoObj->pedido = $Pedido->id;
			$PedidosMonitoradoObj->status_pedido_monitorado = 1;
			$PedidosMonitoradoObj->emissao_data_hora = date('Y-m-d H:i:s', strtotime($Pedido->created_at));
			$PedidosMonitoradoObj->emissao_user = $Pedido->created_by;
			$PedidosMonitoradoObj->save();
		}
	}

	private function checkPedidoMonitorAprovado(PedidoPortal $Pedido, $aprovacao_user)
	{
		$codigo_transportador_retira = '0001';
		if (intval($codigo_transportador_retira) === intval($Pedido->transportadora)) {
			$PedidosMonitoradoObj = PedidosMonitorado::where('pedido', $Pedido->id)->first();
			if (is_null($PedidosMonitoradoObj)) {
				$PedidosMonitoradoObj = new PedidosMonitorado();
				$PedidosMonitoradoObj->estabelecimento = $Pedido->estabelecimento;
				$PedidosMonitoradoObj->pedido = $Pedido->id;
				$PedidosMonitoradoObj->emissao_data_hora = date('Y-m-d H:i:s', strtotime($Pedido->created_at));
				$PedidosMonitoradoObj->emissao_user = $Pedido->created_by;
			}
			$PedidosMonitoradoObj->status_pedido_monitorado = 2;
			$PedidosMonitoradoObj->aprovacao_data_hora = date('Y-m-d H:i:s');
			$PedidosMonitoradoObj->aprovacao_user = $aprovacao_user;
			$PedidosMonitoradoObj->save();
		}
	}

	public function aprovacaoPedido()
	{

		$Pedido = PedidoPortal::find($this->pedido);

		
		$this->checkPedidoMonitorar($Pedido);
		$credito = $this->checkCreditoPedido($Pedido);
		$prametersAprovacao = $this->createPrametersPedido($Pedido);
		// $condicao_pagamento = $this->checkCondicaoPagamentoPedido($Pedido, $prametersAprovacao['prazo_adicional']);
		$preco = $this->checkPrecoPedido($Pedido, $prametersAprovacao['percentual_desconto']);
		$desconto = $this->verificaDesconto($Pedido, $prametersAprovacao['percentual_desconto']);
		$pedido_pre = false;
		if (in_array($Pedido->tipo_venda, ['pre_pago', 'pre_pago_triangular', 'pre_pago_futuro', 'pre_pago_rj_x_sp', 'pre_pago_producao', 'pre_pago_producao_triangular'])) {
			$pedido_pre = true;
		}

		/* Pagamento a Distância Cliente Novo*/
		$cliente_novo_distancia = false;

		$clienteObj = $Pedido->cliente;

		if ($Pedido->cartao == true) {
			if ($Pedido->presencial == false) {
				if (!empty($clienteObj->cliente_desde)) {
					$cpf_cnpj = $clienteObj->cpf_cnpj;

					if (strlen(trim($cpf_cnpj)) == 18) {
						$cpf_cnpj = substr($cpf_cnpj, 0, 10);
					}

					$grupoEmpresarialObj = GrupoEmpresarial::with('participantes')
						->where('raiz_cnpj', $cpf_cnpj)
						->orWhereHas('participantes', function ($query) use ($cpf_cnpj) {
							$query->where('raiz_cnpj', $cpf_cnpj);
						})
						->first();

					$dataHoje = Carbon::today()->subMonths(4);
					$cliente_desde = Carbon::parse($clienteObj->cliente_desde)->setTime(0, 0, 0);

					if ($cliente_desde->gt($dataHoje)) {
						$clientesNasajonQuery = ClienteNasajon::select('nome', 'codigo', 'cpf_cnpj', 'id');

						if (!is_null($grupoEmpresarialObj)) {
							$clientesNasajonQuery->where(function ($query) use ($grupoEmpresarialObj) {
								if (isset($grupoEmpresarialObj->participantes)) {
									foreach ($grupoEmpresarialObj->participantes as $participante) {
										$query->orWhere('cpf_cnpj', 'ilike', $participante->raiz_cnpj . '%');
									}
									$grupo[] = $participante->raiz_cnpj;
								}
								$query->orWhere('cpf_cnpj', 'ilike', $grupoEmpresarialObj->raiz_cnpj . '%');
							});
						} else {
							$cliente_novo_distancia = true;
						}

						$cliente_desde = Carbon::parse($clientesNasajonQuery->min('cliente_desde'))->setTime(0, 0, 0);

						if ($cliente_desde->gt($dataHoje)) {
							$cliente_novo_distancia = true;
						}
					}
				}
				if (!is_null($grupoEmpresarialObj)) {
					$clientesNasajonQuery = ClienteNasajon::select('nome', 'codigo', 'cpf_cnpj', 'id');
					$clientesNasajonQuery->where(function ($query) use ($grupoEmpresarialObj) {
						if (isset($grupoEmpresarialObj->participantes)) {
							foreach ($grupoEmpresarialObj->participantes as $participante) {
								$query->orWhere('cpf_cnpj', 'ilike', $participante->raiz_cnpj . '%');
							}
							$grupo[] = $participante->raiz_cnpj;
						}
						$query->orWhere('cpf_cnpj', 'ilike', $grupoEmpresarialObj->raiz_cnpj . '%');
					});
					$clientesNasajon = $clientesNasajonQuery->get();

					$PedidoPortal = PedidoPortal::whereIn('cod_cliente',  $clientesNasajon->pluck('codigo'))->where('status_pedido', 3)->get();
				} else {
					$PedidoPortal = PedidoPortal::where('cod_cliente', $clienteObj->codigo)->where('status_pedido', 3)->get();
				}

				if ($PedidoPortal->isEmpty()) {
					$cliente_novo_distancia = true;
				}
			}
		}

		/* Cliente com atraso e com crédito */
		$cliente_com_atraso_e_credito = false;

		$posicao_cliente = PosicaoClienteNasajon::where('cod_cliente', $clienteObj->codigo)->first();

		if ($posicao_cliente->dias_maior_titulo_atraso > 30 &&  $Pedido->nome_comprador != 'TEXTIL MN COMERCIO DE TECIDOS E CONFECCOES LTDA') {
			$raiz_cnpj = substr($clienteObj->cpf_cnpj, 0, 10);

			$grupoEmpresarialObj = GrupoEmpresarial::with('participantes')
				->where('raiz_cnpj', $raiz_cnpj)
				->orWhereHas('participantes', function ($query) use ($raiz_cnpj) {
					$query->where('raiz_cnpj', $raiz_cnpj);
				})
				->first();

			$grupo = [];
			if (!is_null($grupoEmpresarialObj)) {
				if (isset($grupoEmpresarialObj->participantes)) {
					foreach ($grupoEmpresarialObj->participantes as $participante) {
						$grupo[] = $participante->raiz_cnpj;
					}
				}

				$grupo[] = $raiz_cnpj;

				$cliente_credito = ClienteCredito::whereIn('raiz_cnpj', $grupo)->orderBy('data_atualizacao', 'desc')->first();
			} else {
				$cliente_credito = ClienteCredito::where('raiz_cnpj', $raiz_cnpj)->orderBy('data_atualizacao', 'desc')->first();
			}

			if (!empty($cliente_credito)) {
				$data_atual = Carbon::today()->addMonths(6)->subDays(90);

				$data_credito = Carbon::parse($cliente_credito->data_atualizacao)->setTime(0, 0, 0)->addMonth(6);

				if ($data_atual->gt($data_credito)) {
					$cliente_com_atraso_e_credito = true;
				}
			}
		}

		if ($cliente_novo_distancia === true || $cliente_com_atraso_e_credito == true) {
			if ($credito === true) {
				$credito = [];
				$credito['existe_limite_credito'] = false;
				$credito['data_limite_credito'] = false;
				$credito['prorrogacao'] = false;
				$credito['limite_credito_disponivel'] = false;
			} else {
				$credito['data_limite_credito'] = false;
			}
		}

		if (
			$credito !== true ||
			$preco !== true ||
			$desconto !== true ||
			$pedido_pre === true
		) {
			$nivel = 1;
			$nivel_aprovacao_preco = 0;

			if ($desconto !== true) {
				$nivel_aprovacao_preco = (int) NivelAprovacao::where('tipo_usuario_id', $desconto)->first()->id;
			}
			if ($preco !== true) {
				$nivel_aprovacao_preco_temp = (int) NivelAprovacao::where('tipo_usuario_id', $preco)->first()->id;
				if ($nivel_aprovacao_preco == 0 || $nivel_aprovacao_preco > $nivel_aprovacao_preco_temp) {
					$nivel_aprovacao_preco = $nivel_aprovacao_preco_temp;
				}
			}
			if (
				$credito === true
			) {
				$nivel = $nivel_aprovacao_preco;
			}
			$check_credito = ($credito === true) ? false : true;
			$check_preco = ($preco === true && $desconto === true) ? false : true;

			$credito_data_limite = ($credito !== true && $credito['data_limite_credito'] === false) ? true : false;
			$credito_sem_limite = ($credito !== true && $credito['existe_limite_credito'] === false) ? true : false;
			$prorrogacao = ($credito !== true && $credito['prorrogacao'] === true) ? true : false;

			if ($prorrogacao === true) {
				$nivel_aprovacao_preco_temp = (int) NivelAprovacao::where('tipo_usuario_id', 15)->first()->id;
				$check_preco = true;
				$nivel_aprovacao_preco = $nivel_aprovacao_preco_temp;
			}

			$preco_limite = true;
			$preco_desconto = ($desconto === true) ? false : true;

			$nivel_aprovacao_credito = 0;
			if ($credito !== true) {
				$nivel_aprovacao_credito = 1;
			}
			$retaguarda = false;
			if ($pedido_pre === true) {
				$nivel_aprovacao_credito = 1;
				$nivel = 1;
				$check_credito = false;
				$retaguarda = true;
			}

			$credito_disponivel = 0;
			if (isset($credito['limite_credito_disponivel']) && !empty($credito['limite_credito_disponivel'])) {
				$credito_disponivel = $credito['limite_credito_disponivel'];
			}
			$this->insertAprovacao($Pedido, $nivel, $check_credito, $check_preco, $credito_sem_limite, $credito_data_limite, $preco_limite, $preco_desconto, $nivel_aprovacao_credito, $nivel_aprovacao_preco, $prorrogacao, $pedido_pre, $retaguarda, $credito_disponivel, $cliente_novo_distancia, $cliente_com_atraso_e_credito);
		} else {
			$request = new Request(['id' => $this->pedido]);

			$this->aprovaPedido($request);
		}
		return true;
	}

	private function verificaDesconto(PedidoPortal $Pedido, $parametrosAprovacao)
	{
		if ($Pedido->valor_desconto > 0) {
			if ((($Pedido->valor_desconto / floatval($Pedido['valor_total']->total)) * 100) <= floatval($parametrosAprovacao[0]['valor'])) {
				return true;
			} else if (
				floatval($parametrosAprovacao[0]['valor']) < (($Pedido->valor_desconto / floatval($Pedido['valor_total']->total)) * 100) &&
				floatval($parametrosAprovacao[1]['valor']) >= (($Pedido->valor_desconto / floatval($Pedido['valor_total']->total)) * 100)
			) {
				return $parametrosAprovacao[1]['tipo_usuario'];
			} else if (
				floatval($parametrosAprovacao[1]['valor']) < (($Pedido->valor_desconto / floatval($Pedido['valor_total']->total)) * 100)
			) {
				return $parametrosAprovacao[2]['tipo_usuario'];
			}
			if (
				(($Pedido->valor_desconto / floatval($Pedido['valor_total']->total)) * 100) >= $parametrosAprovacao[2]['valor'] &&
				(($Pedido->valor_desconto / floatval($Pedido['valor_total']->total)) * 100) < $parametrosAprovacao[1]['valor']
			) {
				return $parametrosAprovacao[2]['tipo_usuario'];
			} elseif (
				(($Pedido->valor_desconto / floatval($Pedido['valor_total']->total)) * 100) >= $parametrosAprovacao[1]['valor'] &&
				(($Pedido->valor_desconto / floatval($Pedido['valor_total']->total)) * 100) < $parametrosAprovacao[2]['valor']
			) {
				return $parametrosAprovacao[1]['tipo_usuario'];
			}
		}

		return true;
	}

	private function insertAprovacao(PedidoPortal $Pedido, $nivel_aprovacao, $criterio_credito = false, $criterio_preco = false, $credito_sem_limite, $credito_data_limite = false, $preco_limite = false, $preco_desconto = true, $nivel_aprovacao_credito = 0, $nivel_aprovacao_preco = 0, $prorrogacao = false, $prepago = false, $retaguarda = false, $credito_disponivel = 0, $cliente_novo_distancia = false, $cliente_com_atraso_e_credito = false)
	{
		if (!empty(AprovacaoDePedido::where('pedido_id', $Pedido->id)->get()->toArray())) {
			$AprovacaoDePedido = AprovacaoDePedido::find(AprovacaoDePedido::where('pedido_id', $Pedido->id)->first()->pluck('id')[0]);
		} else {
			$AprovacaoDePedido = new AprovacaoDePedido();
			$AprovacaoDePedido->pedido_id = $Pedido->id;
		}

		$Pedido->codigo_operacao = $this->getCodigoOperacao($Pedido);

		$Pedido->save();

		$AprovacaoDePedido->nivel_aprovacao = $nivel_aprovacao;
		$AprovacaoDePedido->credito = $criterio_credito;
		$AprovacaoDePedido->preco = $criterio_preco;

		$AprovacaoDePedido->credito_sem_limite = $credito_sem_limite;
		$AprovacaoDePedido->credito_data_limite = $credito_data_limite;
		$AprovacaoDePedido->preco_limite = $preco_limite;
		$AprovacaoDePedido->credito = $criterio_credito;
		$AprovacaoDePedido->preco_desconto = $preco_desconto;
		$AprovacaoDePedido->nivel_aprovacao_credito = $nivel_aprovacao_credito;
		$AprovacaoDePedido->nivel_aprovacao_preco = $nivel_aprovacao_preco;
		$AprovacaoDePedido->prorrogacao = $prorrogacao;
		$AprovacaoDePedido->pedido_pre = $prepago;
		$AprovacaoDePedido->retaguarda = $retaguarda;
		$AprovacaoDePedido->credito_disponivel = $credito_disponivel;
		$AprovacaoDePedido->cliente_novo_distancia = $cliente_novo_distancia;
		$AprovacaoDePedido->cliente_com_atraso_e_credito = $cliente_com_atraso_e_credito;

		$AprovacaoDePedido->save();
	}

	private function checkCreditoPedido(PedidoPortal $Pedido)
	{
		$Cliente = $Pedido['cliente'];

		$parametros = ParametrosAprovacaoPedido::select('maximo_tempo_inativo', 'maximo_atraso_medio', 'maximo_ultimo_atraso', 'maximo_maior_atraso', 'maximo_duplicatas_vencidas', 'maximo_de_limite_credito')->where('estabelecimento', str_pad($Pedido->estabelecimento, 2, '0', STR_PAD_LEFT))->first();

		$parametro_inativo_maisde 					= intval($parametros->maximo_tempo_inativo);
		$parametro_atraso_medio 					= intval($parametros->maximo_atraso_medio);
		$parametro_ultimo_atraso 					= intval($parametros->maximo_ultimo_atraso);
		$parametro_maior_atraso 					= intval($parametros->maximo_maior_atraso);
		$parametro_duplicatas_vencidas_a_mais 		= intval($parametros->maximo_duplicatas_vencidas);
		$data_hoje = Carbon::now()->setTime(0, 0, 0);

		if (in_array($Cliente->codigo, $this->codigo_cliente_balcao)) {
			return true;
		}

		$razao_cnpj_textil = '06311274';

		$cpf_cnpj = $Cliente->cpf_cnpj;
		$codcads = [$Cliente->codigo];
		$ids = [$Cliente->id];

		$cnpjs = [$cpf_cnpj];

		$check_limite_credito = true;
		$check_data_limite_credito = true;

		$raiz_cnpj = $cpf_cnpj;

		if (strlen(trim($cpf_cnpj)) == 18) {
			$cpf_cnpj = substr($cpf_cnpj, 0, 10);
		}

		$raiz_cnpj = $cpf_cnpj;
		if (
			$razao_cnpj_textil === str_replace('.', '', $raiz_cnpj)
		) {
			return true;
		}

		$grupoEmpresarialObj = GrupoEmpresarial::with('participantes')
			->where('raiz_cnpj', $raiz_cnpj)
			->orWhereHas('participantes', function ($query) use ($raiz_cnpj) {
				$query->where('raiz_cnpj', $raiz_cnpj);
			})->first();

		$clientesNasajonQuery = ClienteNasajon::select('*');
		$clientesNasajonQuery->where("codigo", "!=", $Cliente->codigo);

		if (!is_null($grupoEmpresarialObj)) {
			$clientesNasajonQuery->where(function ($query) use ($grupoEmpresarialObj) {
				if (isset($grupoEmpresarialObj->participantes)) {
					foreach ($grupoEmpresarialObj->participantes as $participante) {
						$query->orWhere('cpf_cnpj', 'like', $participante->raiz_cnpj . '%');
					}
					$grupo[] = $participante->raiz_cnpj;
				}

				$query->orWhere('cpf_cnpj', 'like', $grupoEmpresarialObj->raiz_cnpj . '%');
			});

			$grupo = array_merge([$grupoEmpresarialObj->raiz_cnpj], $grupoEmpresarialObj->participantes->pluck('raiz_cnpj')->toArray());
		} else {
			$clientesNasajonQuery->where('cpf_cnpj', 'like', $raiz_cnpj . '%');
			$grupo = [$raiz_cnpj];
		}

		$clientesNasajon = $clientesNasajonQuery->get()->toArray();
		unset($clientesNasajonQuery);

		foreach ($clientesNasajon as $key => $value) {
			$codcads[] = $value["codigo"];
			$cnpjs[] = $value["cpf_cnpj"];
			$ids[] = $value['id'];
		}
		unset($clientesNasajon);

		$limite_credito = 0;
		$ClienteCreditoObj = ClienteCredito::whereIn('raiz_cnpj', $grupo)->get();
		if (is_null($ClienteCreditoObj)) {
			$check_limite_credito = false;
		} else {
			$limite_credito = (float) $ClienteCreditoObj->sum('valor');

			$data_atulizacaco_limite = Carbon::parse($ClienteCreditoObj->min('data_atualizacao'))->setTime(0, 0, 0);
			$maximo_de_limite_credito = $parametros->maximo_de_limite_credito;
			$data_atulizacaco_limite->addMonths($maximo_de_limite_credito);
			if ($data_hoje->gt($data_atulizacaco_limite)) {
				$check_data_limite_credito = false;
			}
		}
		$nota_credito = 0;
		$notasCredito = NotasCreditoReceberNasajon::whereIn('cod_cliente', $codcads)
			->get();

		$nota_credito += $notasCredito->sum('valor');

		$limite_credito += $nota_credito;

		$cliente_duplicata_aberta 				= [];
		$cliente_cheques_aberta 				= [];
		$cliente_cheque_sem_fundo_lucros_perdas = false;
		$cliente_cheque_sem_fundo_negociacao 	= false;

		$valor_pedido = floatval($Pedido['valor_total']->total);
		$pedidos_em_aberto_nasjon = PedidosVendaNasajon::select('*')
			->whereIn('situacao_descricao', ['Em Faturamento', 'Em separação', 'Aberto', 'Aguardando Documento'])
			->where(function ($query) {
				$query->where('grupodeoperacao', 'VENDA')
					->orWhereNull('grupodeoperacao');
			})
			->where('rascunho', false)
			->whereIn('cliente', $ids)->sum('valor');
		$pedidos_em_aberto = (float) $pedidos_em_aberto_nasjon;
		unset($pedidos_em_aberto_nasjon);

		$PedidoPortalEmAberto = PedidoPortal::select('*')
			->whereNotIn('status_pedido', [1, 3, 5, 7])
			->where('id', '!=', $Pedido->id)
			->whereIn('cod_cliente', $codcads)
			->get();
		$total_pedidos_em_aberto = 0;
		$PedidoPortalEmAberto->each(function ($pedido) use (&$total_pedidos_em_aberto) {
			if (isset($pedido->valor_total->total)) {
				$total_pedidos_em_aberto += $pedido->valor_total->total;
			}
		});
		unset($PedidoPortalEmAberto);
		$pedidos_em_aberto += (float) $total_pedidos_em_aberto;

		$titulosNasajon = TitulosEmAbertoNasajon::whereIn('cod_cliente', $codcads)->get();
		$titulos_faturados = ['' => 0];
		$titulosNasajon->each(function ($item) use (&$titulos_faturados) {
			$key = $item->numero . '' . $item->codigo;
			if (!isset($titulos_faturados[$key])) {
				$titulos_faturados[$key] = floatval($item->saldotitulo);
			}
		});

		$cliente_duplicata_aberta['data'] = $titulosNasajon->min('vencimento');
		$cliente_duplicata_aberta['total'] = (float) array_sum($titulos_faturados);
		if (is_null($cliente_duplicata_aberta['data'])) {
			$cliente_duplicata_aberta['data'] = date('Y-m-d 00:00:00');
		}

		$ChequesRecebidoObj = ChequesEmAbertoNasajon::whereIn('cod_cliente', $codcads);
		$cliente_cheques_aberta['data'] = $ChequesRecebidoObj->min('data_vencimento');
		$cliente_duplicata_aberta['total'] += (float) $ChequesRecebidoObj->sum('valor');
		unset($ChequesRecebidoObj);

		$check_prepago = false;

		$pedidosPrePagosObj = PedidosPrePago::with(['pedidoNasajon' => function ($query) {
			$query->where('grupodeoperacao', 'VENDA');
		}, 'pedidoNasajon.nota'])
			->whereHas('pedido', function ($query) use ($codcads) {
				$query->whereIn('cod_cliente', $codcads);
			})
			->get();

		$pedidosPrePagosObj = $pedidosPrePagosObj->filter(function ($value) {
			return isset($value->pedidoNasajon) && isset($value->pedidoNasajon->nota);
		});

		$valor_total_prepago = $pedidosPrePagosObj->sum('valor') ?? 0;
		$valor_baixado_prepago = $pedidosPrePagosObj->sum('valor_pago') ?? 0;
		$total_pre_pagos = $valor_total_prepago - $valor_baixado_prepago;

		if ($total_pre_pagos > 0) {
			$check_prepago = true;
		}

		$ChequesObj = Cheque::whereIn('cliente_cpf_cnpj', $cnpjs)->whereHas('pedidos_prepagos')->where('bom_para', '>', Carbon::Now()->format('Y-m-d'))->where('tipo', 'cheque')->get();

		$chque_pre = $ChequesObj->sum('valor');

		$total_pre_pagos += $chque_pre;

		if (!is_null($cliente_cheques_aberta['data'])) {
			if (strtotime($cliente_duplicata_aberta['data']) > strtotime($cliente_cheques_aberta['data'])) {
				$cliente_duplicata_aberta['data'] = $cliente_cheques_aberta['data'];
			}
		}

		$check_prorrogacao = false;
		if ($titulosNasajon->where('tem_prorrogacao', true)->isNotEmpty()) {
			$check_prorrogacao = true;
		}
		unset($titulosNasajon);

		$cliente_duplicata_aberta['data'] = Carbon::parse($cliente_duplicata_aberta['data'])->setTime(0, 0, 0);

		if (
			$Pedido->cartao == true &&
			$Pedido->presencial == false
		) {
			return [
				'prorrogacao' => $check_prorrogacao,
				'existe_limite_credito' => $check_limite_credito,
				'data_limite_credito' => $check_data_limite_credito,
				'limite_credito_disponivel' <= ($limite_credito <= 0 || $limite_credito <= ($valor_pedido + $pedidos_em_aberto + floatval($cliente_duplicata_aberta['total']))),
				'duplicatas_vencidas_a_mais' => $cliente_duplicata_aberta['data']->lt($data_hoje)
			];
		}

		if (
			in_array($Pedido['condicao_pagamento_detalhes']['descricao'], $this->condicao_de_pagamento_livre)
		) {
			if (
				$check_prorrogacao === true ||
				$cliente_duplicata_aberta['data']->lt($data_hoje) ||
				$check_prepago === true
			) {
				return [
					'prorrogacao' => $check_prorrogacao,
					'existe_limite_credito' => $check_limite_credito,
					'data_limite_credito' => $check_data_limite_credito,
					'limite_credito_disponivel' <= ($limite_credito <= 0 || $limite_credito <= ($valor_pedido + $pedidos_em_aberto + floatval($cliente_duplicata_aberta['total']))),
					'duplicatas_vencidas_a_mais' => $cliente_duplicata_aberta['data']->lt($data_hoje)
				];
			} else {
				return true;
			}
		}

		if (
			$check_limite_credito === false ||
			$check_data_limite_credito === false ||
			$limite_credito <= 0 ||
			$check_prorrogacao === true ||
			$limite_credito <= ($valor_pedido + $pedidos_em_aberto + floatval($cliente_duplicata_aberta['total']) + $total_pre_pagos) ||
			$cliente_duplicata_aberta['data']->lt($data_hoje) ||
			$check_prepago === true
		) {
			return [
				'prorrogacao' => $check_prorrogacao,
				'existe_limite_credito' => $check_limite_credito,
				'data_limite_credito' => $check_data_limite_credito,
				'limite_credito_disponivel' <= ($limite_credito <= 0 || $limite_credito <= ($valor_pedido + $pedidos_em_aberto + floatval($cliente_duplicata_aberta['total']))),
				'duplicatas_vencidas_a_mais' => $cliente_duplicata_aberta['data']->lt($data_hoje)
			];
		} else {
			return true;
		}
	}

	private function createPrametersPedido(PedidoPortal $Pedido)
	{
		$estabelecimento = $Pedido->estabelecimento;
		$ParametrosAprovacaoObj = ParametrosAprovacao::select('tipo_usuario_id', 'percentual_desconto', 'prazo_adicional')->where('estabelecimento', str_pad($estabelecimento, 2, '0', STR_PAD_LEFT))->orderby('tipo_usuario_id')->get();

		$parametrosAprovacao = [
			"percentual_desconto" => [],
			"prazo_adicional" => []
		];

		foreach ($ParametrosAprovacaoObj as $Parametro) {
			$parametrosAprovacao['percentual_desconto'][] = ['tipo_usuario' => $Parametro->tipo_usuario_id, 'valor' => floatval($Parametro->percentual_desconto)];
			$parametrosAprovacao['prazo_adicional'][] = ['tipo_usuario' => $Parametro->tipo_usuario_id, 'valor' => floatval($Parametro->prazo_adicional)];
		}

		return $parametrosAprovacao;
	}

	public function checkPrecoPedido(PedidoPortal $Pedido, $parametrosAprovacao)
	{

		$razao_cnpj_textil = '06311274';

		$Cliente = $Pedido['cliente'];
		$cpf_cnpj = $Cliente->cpf_cnpj;
		if (strlen(trim($cpf_cnpj)) == 18) {
			$cpf_cnpj = substr($cpf_cnpj, 0, 10);
		}

		$raiz_cnpj = $cpf_cnpj;

		if (
			$razao_cnpj_textil === str_replace(".", '', $raiz_cnpj)
		) {
			return true;
		}

		$itens = $Pedido['itens_pedido'];
		$condicao_pagamento = $Pedido['condicao_pagamento_detalhes'];
		if (!empty($condicao_pagamento) && intval($condicao_pagamento->media) > 120) {
			return $parametrosAprovacao[2]['tipo_usuario'];
		}
		$origem = 'SP';
		switch (intval($Pedido->estabelecimento)) {
			case 3:
				$origem  = "RO";
				break;
			case 4:
				$origem = "TO";
				break;
			default:
				$origem = 'SP';
				break;
		}
		if ($Pedido->rj_x_sp == true) {
			$origem = 'SP';
		}

		$PedidoPortalControllerObj = new PedidoPortalController();
		$preco_frete = $PedidoPortalControllerObj->fretePreco($Pedido);
		$frete = $preco_frete['preco'];

		$estadoObj = CepEstado::find($Pedido['cliente']->uf);

		$arr['estado'] = $estadoObj->uf;
		$arr['origem'] = $origem;
		$arr['prazo_medio'] = $condicao_pagamento->media ?? 0;
		$arr['moeda'] = ($Pedido->pedido_futuro === true && floatval($Pedido->estabelecimento) == 3) ? 'dolar' : 'real';
		$arr['frete'] = $frete;
		$arr['tipo_cliente'] = ($Pedido->cliente->inscricaoestadual == 'ISENTO' ||
			intval($Pedido->cliente->indicadorinscricaoestadual) == 2 ||
			intval($Pedido->cliente->indicadorinscricaoestadual) == 9
		) ? 'isento' : 'juridico';

		$perfil_aprovador = null;

		foreach ($itens as $key => $item) {
			$internacional = 'false';
			$aliquotaObj = AliquotaPreco::where('origem', $origem)
				->where('estado', $Pedido['cliente']->uf)
				->where('internacional', $internacional)
				->first();

			if ($Pedido->tipo_venda == 'isento') {
				$arr['aliquota'] = $aliquotaObj->icms_venda_cliente_isento;
			} else {
				$arr['aliquota'] = $aliquotaObj->icms_venda;
			}

			$arr['produto'] = $item->cod_produto;

			$arr['promocao'] = true;
			$arr['cliente'] = $Pedido->cod_cliente;
			$arr['codigo_vendedor'] = $Pedido->usuario_detalhes->codigo_representante;

			if (empty($Pedido->detalhesProjeto)) {
				$listaDePrecosObj = new ListagemDePrecosController();
				$filter_request = new ListaDePrecosRequest($arr);
				$arr_result = $listaDePrecosObj->filter($filter_request, true, false, true, false, false, false, false, false, false);
				if (empty($arr_result)) {
					continue;
				}
				$arr_result = $arr_result[0];


				$valor_colunas = [
					'A' => 0.0,
					'B' => 0.0,
					'C' => 0.0
				];

				$valor_colunas['A'] = parserNumber($arr_result['coluna_a']);
			} else {
				$valor_colunas['A'] = $Pedido->detalhesProjeto->itens->where('codigo_produto', $item->cod_produto)->first()->custo;
			}

			$preco = floatval($item->preco_unitario);
			if ($Pedido->metragem_exata == true) {
				$preco = floatval($item->preco_original);
			}

			if ($preco < $valor_colunas['A']) {
				if (
					($preco >= ($valor_colunas['A'] * (1 - ($parametrosAprovacao[2]['valor'] / 100))) &&
						$preco <  ($valor_colunas['A'] * (1 - ($parametrosAprovacao[1]['valor'] / 100)))
					) ||
					$preco < ($valor_colunas['A'] * (1 - ($parametrosAprovacao[2]['valor'] / 100)))
				) {
					return $parametrosAprovacao[2]['tipo_usuario'];
				} else if (
					$preco >= ($valor_colunas['A'] * (1 - ($parametrosAprovacao[1]['valor'] / 100))) &&
					$preco <  ($valor_colunas['A'] * (1 - ($parametrosAprovacao[0]['valor'] / 100)))
				) {
					return $parametrosAprovacao[1]['tipo_usuario'];
				}
			}
		}

		return true;
	}

	public function alteraPedido(Request $request)
	{

		$aprovacaoObj =  AprovacaoDePedido::findOrFail($request->id);
		$pedidoPortalObj = PedidoPortal::findOrFail($aprovacaoObj->pedido_id);

		$aprovacaoObj->status = $request->status;
		$pedidoPortalObj->status_pedido = $request->status;

		$aprovacaoObj->save();
		$pedidoPortalObj->save();

		return response();
	}

	public function aprovaPedido(Request $request)
	{
		$fields = $request->only('id');
		
		$pedido = $fields['id'];
		$AprovacaoDePedidoObj = AprovacaoDePedido::where('pedido_id', $pedido)->first();
		$pedidoObj = PedidoPortal::with(['detalhesTransportador','cliente.devolucaos' => function ($query) {
			$query->whereHas('motivo_devolucao', function ($query) {
				$query->where('assinatura_pedido', 'sim');
			});
		}])->findOrFail($pedido);

		$netrin_ok = true;

		//$netrin_ok = $this->checkNetrin($pedidoObj);

		if ($netrin_ok ==false) {
			$error = [
				'status' => 'error',
				'message' => 'O Cliente Aguardando Atualização Cadastral, favor verificar o cadastro! ' .$pedido,
				'errors' => [
					'receita' => 'Receita não encontrado'
				]
			];

			return response()->json($error, 422);
		}


		$historicoPedidoObj = new HistoricoPedido();

		if (in_array($pedidoObj->tipo_venda, ['producao', 'producao_triangular', 'pre_pago_producao', 'pre_pago_producao_triangular'])) {
			$necessidadeComprasControllerObj = new NecessidadeComprasController;
			$necessidadeComprasControllerObj->adicionarAtravesPedido($pedidoObj);
		}

		if (empty($pedidoObj->usuario_detalhes->vendedor_nasajon)) {
			$error = [
				'status' => 'error',
				'message' => 'O vendedor não encontrado, favor verificar o cadastro!',
				'errors' => [
					'vendedor' => 'Vendedor não encontrado'
				]
			];

			return response()->json($error, 422);
		}

		if (!is_null($AprovacaoDePedidoObj)) {
			if ($pedidoObj->status_pedido == 12) {
				$AprovacaoDePedidoObj->delete();
				$AprovacaoDePedidoObj->save();

				return response()
					->json(
						[
							'status' => 'success',
							'message' => 'O pedido foi aprovado e aguarda processamento.',
							'error' => [],
							'response' => []
						],
						200
					);
			}
			if (
				$AprovacaoDePedidoObj->retaguarda == true &&
				(empty($AprovacaoDePedidoObj->user_aprovacao_pre_1auth)
				) &&
				(Auth::id() == $this->usuarioPreAuth1 ||
					Auth::id() == $this->usuarioPreAuth2
				)
			) {
				if (
					empty($AprovacaoDePedidoObj->user_aprovacao_pre_1auth)
				) {
					$historicoPedidoObj->pedido = $pedidoObj->id;
					$historicoPedidoObj->novo = '';
					$historicoPedidoObj->natureza = 'Aprovação de retaguarda usuario 1';
					$historicoPedidoObj->created_by = Auth::id();
					$historicoPedidoObj->save();

					$AprovacaoDePedidoObj->user_aprovacao_pre_1auth = Auth::id();
					$AprovacaoDePedidoObj->data_aprovacao_pre_1auth = Carbon::now();
					$AprovacaoDePedidoObj->save();
				}
			}

			if (
				$AprovacaoDePedidoObj->credito == true &&
				$AprovacaoDePedidoObj->preco == true &&
				empty($AprovacaoDePedidoObj->aprovacao_credito_user_id) &&
				empty($AprovacaoDePedidoObj->aprovacao_preco_user_id)
			) {
				if (strtolower(Auth::user()->tipo_usuario->nome) == 'credito') {
					$historicoPedidoObj->pedido = $pedidoObj->id;
					$historicoPedidoObj->novo = '';
					$historicoPedidoObj->natureza = 'Aprovação de pedido parado em crédito';
					$historicoPedidoObj->created_by = Auth::id();
					$historicoPedidoObj->save();

					$AprovacaoDePedidoObj->aprovacao_credito_user_id = Auth::id();
				} else {
					$historicoPedidoObj->pedido = $pedidoObj->id;
					$historicoPedidoObj->novo = '';
					$historicoPedidoObj->natureza = 'Aprovação de pedido parado em preço';
					$historicoPedidoObj->created_by = Auth::id();
					$historicoPedidoObj->save();

					$AprovacaoDePedidoObj->aprovacao_preco_user_id = Auth::id();
				}
				$AprovacaoDePedidoObj->save();
				$this->atualizarDataPrevisaoEntregaOriginal($pedidoObj);
				return response()
					->json(
						[
							'status' => 'success',
							'message' => 'O pedido foi aprovado.',
							'error' => [],
							'response' => []
						],
						200
					);
			} elseif (
				$AprovacaoDePedidoObj->credito == true &&
				$AprovacaoDePedidoObj->preco == true &&
				(!empty($AprovacaoDePedidoObj->aprovacao_credito_user_id) ||
					!empty($AprovacaoDePedidoObj->aprovacao_preco_user_id)
				)
			) {
				if (strtolower(Auth::user()->tipo_usuario->nome) == 'credito') {
					$historicoPedidoObj->pedido = $pedidoObj->id;
					$historicoPedidoObj->novo = '';
					$historicoPedidoObj->natureza = 'Aprovação de pedido parado em crédito';
					$historicoPedidoObj->created_by = Auth::id();
					$historicoPedidoObj->save();

					$AprovacaoDePedidoObj->aprovacao_credito_user_id = Auth::id();
				} else {
					$historicoPedidoObj->pedido = $pedidoObj->id;
					$historicoPedidoObj->novo = '';
					$historicoPedidoObj->natureza = 'Aprovação de pedido parado em preço';
					$historicoPedidoObj->created_by = Auth::id();
					$historicoPedidoObj->save();

					$AprovacaoDePedidoObj->aprovacao_preco_user_id = Auth::id();
				}

				if (Auth::user()->tipo_usuario_id == 1 && empty($AprovacaoDePedidoObj->aprovacao_credito_user_id)) {
					$historicoPedidoObj->pedido = $pedidoObj->id;
					$historicoPedidoObj->novo = '';
					$historicoPedidoObj->natureza = 'Aprovação de pedido parado em crédito';
					$historicoPedidoObj->created_by = Auth::id();
					$historicoPedidoObj->save();

					$AprovacaoDePedidoObj->aprovacao_credito_user_id = Auth::id();
				}

				$AprovacaoDePedidoObj->save();
			}

			if (
				$AprovacaoDePedidoObj->credito == true &&
				$AprovacaoDePedidoObj->preco == true &&
				(empty($AprovacaoDePedidoObj->aprovacao_credito_user_id) ||
					empty($AprovacaoDePedidoObj->aprovacao_preco_user_id)
				)
			) {
				$this->atualizarDataPrevisaoEntregaOriginal($pedidoObj);
				return response()->json(
					[
						'status' => 'success',
						'message' => 'O pedido foi aprovado.',
						'error' => [],
						'response' => []
					],
					200
				);
			}
		} else {

			$AprovacaoDePedidoObj = new AprovacaoDePedido;

			$AprovacaoDePedidoObj->pedido_id = $pedidoObj->id;
			$AprovacaoDePedidoObj->nivel_aprovacao = 1;
			$AprovacaoDePedidoObj->aprovador_id = 1;
			$AprovacaoDePedidoObj->save();

			$historicoPedidoObj->pedido = $pedidoObj->id;
			$historicoPedidoObj->novo = '';
			$historicoPedidoObj->natureza = 'Aprovado pelo sistema';
			$historicoPedidoObj->created_by = 1;
			$historicoPedidoObj->save();
		}

		if (
			$AprovacaoDePedidoObj->retaguarda == true &&
			(empty($AprovacaoDePedidoObj->user_aprovacao_pre_1auth)
			)
		) {

			if (
				$AprovacaoDePedidoObj->preco == true &&
				empty($AprovacaoDePedidoObj->aprovacao_preco_user_id)
			) {
				$historicoPedidoObj->pedido = $pedidoObj->id;
				$historicoPedidoObj->novo = '';
				$historicoPedidoObj->natureza = 'Aprovação de pedido parado em preço';
				$historicoPedidoObj->created_by = Auth::id();
				$historicoPedidoObj->save();

				$AprovacaoDePedidoObj->aprovacao_preco_user_id = Auth::id();
				$AprovacaoDePedidoObj->save();
			}

			if (
				$AprovacaoDePedidoObj->credito == true &&
				empty($AprovacaoDePedidoObj->aprovacao_credito_user_id) &&
				strtolower(Auth::user()->tipo_usuario->nome) == 'credito'
			) {
				$historicoPedidoObj->pedido = $pedidoObj->id;
				$historicoPedidoObj->novo = '';
				$historicoPedidoObj->natureza = 'Aprovação de pedido parado em crédito';
				$historicoPedidoObj->created_by = Auth::id();
				$historicoPedidoObj->save();

				$AprovacaoDePedidoObj->aprovacao_credito_user_id = Auth::id();
				$AprovacaoDePedidoObj->save();
			}
			$this->atualizarDataPrevisaoEntregaOriginal($pedidoObj);
			return response()
				->json(
					[
						'status' => 'success',
						'message' => 'O pedido foi aprovado.',
						'error' => [],
						'response' => []
					],
					200
				);
		}

		if (
			$pedidoObj->cartao == true &&
			$pedidoObj->status_pedido == 9 &&
			isset($pedidoObj->cielo[0]) &&
			$pedidoObj->cielo[0]->pago == false
		) {
			$this->atualizarDataPrevisaoEntregaOriginal($pedidoObj);
			return response()
				->json(
					[
						'status' => 'success',
						'message' => 'O pedido foi aprovado e aguarda processamento.',
						'error' => [],
						'response' => []
					],
					200
				);
		}

		$ultima_devolucao = $pedidoObj->cliente->devolucaos->pluck('created_at')->max();

		if (!empty($ultima_devolucao)) {
			if (empty($pedidoObj->clicksign_documentos_id)) {

				$PedidoPortal = PedidoPortal::with(['clicksignDocumento.clicksignSignatarioDocumento'])->where('data_pedido', '>=', $ultima_devolucao->format('Y-m-d'))
					->where('cod_cliente', $pedidoObj->cliente->codigo)
					->whereNotNull('clicksign_documentos_id')
					->get();

				$pedidos_assinados = 0;
				foreach ($PedidoPortal as $assinatura) {
					$assinaturas = $assinatura->clicksignDocumento->clicksignSignatarioDocumento->pluck('assinou_como')->count();
					if ($assinatura->clicksignDocumento->clicksignSignatarioDocumento->where('assinou_como', '!=', null)->pluck('assinou_como')->count() == $assinaturas) {
						$pedidos_assinados += 1;
					}
				}

				if ($pedidos_assinados < 3) {
					$pedidoPortalControllerObj = new PedidoPortalController;
					$signatarios = $pedidoPortalControllerObj->gerarSignatario($pedidoObj->id);
					$path_pdf = $pedidoPortalControllerObj->gerarArquivoPdf($pedidoObj->id);

					$pedidoObj->clicksign_documentos_id = 12;
					$pedidoObj->status_pedido = 12;
					$pedidoObj->save();

					try {
						$assinaturaEletronicaClicksignControllerObj = new AssinaturaEletronicaClicksignController;
						$retorno_clicksign = $assinaturaEletronicaClicksignControllerObj->solicitarAssinaturaEmail($signatarios, $path_pdf, 'pedido');
						if ($retorno_clicksign->getData()->status === 'error') {
							throw new \Exception;
						}
						$pedidoObj->clicksign_documentos_id = decrypt($retorno_clicksign->getData()->response->id);
						$pedidoObj->save();

						$AprovacaoDePedidoObj->delete();
						$AprovacaoDePedidoObj->save();

						$this->atualizarDataPrevisaoEntregaOriginal($pedidoObj);

						return response()
							->json(
								[
									'status' => 'success',
									'message' => 'O pedido foi aprovado e aguarda processamento.',
									'error' => [],
									'response' => []
								],
								200
							);
					} catch (\Exception $e) {
						$pedidoObj->status_pedido = 1;
						$pedidoObj->save();
					}
				}
			}
		}


		$data_previsao_entrega = $pedidoObj->data_previsao_entrega;
		if (!empty($data_previsao_entrega)) {
			$data_previsao_entrega = Carbon::parse($data_previsao_entrega)->setTime(0, 0, 0);
		} else {
			$data_previsao_entrega = Carbon::today();
		}

		if (
			!in_array($pedidoObj->tipo_venda, ['producao', 'producao_triangular', 'pre_pago_producao', 'pre_pago_producao_triangular']) &&
			$pedidoObj->pedido_futuro == false &&
			$data_previsao_entrega->gt(Carbon::today())
		) {
			$pedidoObj->status_pedido = 10;
			$pedidoObj->save();

			$AprovacaoDePedidoObj->delete();
			$AprovacaoDePedidoObj->save();

			$this->atualizarDataPrevisaoEntregaOriginal($pedidoObj);

			return response()
				->json(
					[
						'status' => 'success',
						'message' => 'O pedido foi aprovado e aguarda processamento.',
						'error' => [],
						'response' => []
					],
					200
				);
		}

		if (
			in_array($pedidoObj->condicao_pagamento, $this->condicao_de_pagamento_usar_credito) &&
			$pedidoObj->pedido_futuro == false
		) {
			$pedidoObj->status_pedido = 9;
			$pedidoObj->save();

			$pedidoUsarCreditoObj = PedidoUsarCredito::select()->where('pedido_id', $pedidoObj->id)->first();

			if (empty($pedidoUsarCreditoObj)) {
				$pedidoUsarCreditoObj = new PedidoUsarCredito;
				$pedidoUsarCreditoObj->pedido_id = $pedidoObj->id;
				$pedidoUsarCreditoObj->liberado = false;
				$pedidoUsarCreditoObj->data_bloqueio = Carbon::now();
				$pedidoUsarCreditoObj->created_by = Auth::id();
			} else {
				$pedidoUsarCreditoObj->liberado = false;
				$pedidoUsarCreditoObj->updated_by = Auth::id();
			}

			$pedidoUsarCreditoObj->save();

			$AprovacaoDePedidoObj->delete();
			$AprovacaoDePedidoObj->save();

			$this->enviarEmailEsperandoPagamento($pedidoObj);

			$this->atualizarDataPrevisaoEntregaOriginal($pedidoObj);

			return response()
				->json(
					[
						'status' => 'success',
						'message' => 'O pedido foi aprovado e aguarda processamento.',
						'error' => [],
						'response' => []
					],
					200
				);
		}


		$return = $this->processaIntegracaoPedidoNasajon($pedidoObj, $fields);
		if (!empty($return)) {
			if ($return['status'] == 'success') {
				return response()->json($return);
			}
			return response()->json($return, 422);
		}

		$this->atualizarDataPrevisaoEntregaOriginal($pedidoObj);

		return response()
			->json(
				[
					'status' => 'success',
					'message' => 'O pedido foi aprovado e aguarda processamento.',
					'error' => [],
					'response' => []
				],
				200
			);
	}

	public function recusarPedidoModal(Request $request)
	{
		$fields = $request->only('id');

		$aprovacaoObj = AprovacaoDePedido::with('pedido', 'pedido.cliente', 'pedido.usuario_detalhes')->findOrFail($fields['id']);
		$estabelecimentos = returnEmpresasNasajonView();

		$info = [
			'id' => $aprovacaoObj->id,
			'estabelecimento' => $estabelecimentos[$aprovacaoObj->pedido['estabelecimento']],
			'cliente' => $aprovacaoObj->pedido->cliente['NOME'],
			'valor' => $aprovacaoObj->pedido->valor_total['total'],
			'vendedor' => $aprovacaoObj->pedido->usuario_detalhes['name'],
			'criterio_credito' => $aprovacaoObj->credito ? 'Sim' : 'Não',
			'criterio_condicao_pagamento' => $aprovacaoObj->condicao_pagamento ? 'Sim' : 'Não',
			'criterio_preco' => $aprovacaoObj->preco ? 'Sim' : 'Não',
		];
		$MotivoRecusaPedidoObj = MotivoRecusaPedido::all();
		$motivos = ['' => ''];
		foreach ($MotivoRecusaPedidoObj as $key => $value) {
			$motivos[$value['motivo']] = $value['motivo'];
		}

		return view("programs.aprovacao_pedido.recusar")->with(['info' => $info, 'motivos' => $motivos]);
	}

	public function recusarPedido(Request $request)
	{
		$fields = $request->only('id', 'motivo_rejeicao', 'revisar', 'mensagem');

		if (empty(trim($fields['motivo_rejeicao']) || !isset($fields['motivo_rejeicao'])) || empty($fields['revisar'])) {
			$error = [
				'status' => 'error',
				'message' => 'Informações inválidas',
				'errors' => [
					'motivo_rejeicao' => 'Digite uma justificativa'
				]
			];

			if (empty($fields['revisar'])) {
				$error = [
					'status' => 'error',
					'message' => 'Informações inválidas',
					'errors' => [
						'revisar' => 'Campo obrigatório'
					]
				];
			}

			return response()->json($error, 422);
		}

		$aprovacaoObj = AprovacaoDePedido::with(['pedido.usuario_detalhes.supervisor', 'pedido.cliente'])->find($fields['id']);
		$cliente = $aprovacaoObj->pedido->cliente;

		if ($fields['revisar'] === "sim") {
			if (empty(trim($fields['mensagem']))) {
				$error = [
					'status' => 'error',
					'message' => 'Informações inválidas',
					'errors' => [
						'mensagem' => 'Campo obrigatório'
					]
				];

				return response()->json($error, 422);
			}
			$EmailObj = new EmailController();
			$email_send = [];
			$email_vendedor = (!empty($aprovacaoObj->pedido->usuario_detalhes->email)) ? $aprovacaoObj->pedido->usuario_detalhes->email : null;
			$email_gerente = (!empty($aprovacaoObj->pedido->usuario_detalhes->supervisor->email)) ? $aprovacaoObj->pedido->usuario_detalhes->supervisor->email : null;
			$email_send = [$email_vendedor, $email_gerente];
			$nome_cliente = '';
			$nome_cliente = $cliente->nome;

			if (!empty($email_send)) {
				$variaveis = [
					'nome_cliente' => $nome_cliente,
					'numero_pedido' => $aprovacaoObj->pedido->id,
					'motivo_recusa' => $fields['motivo_rejeicao'],
					'revisar_mensagem' => $fields['mensagem'],
				];
				$returnEmail = $EmailObj->sendEmailToken($aprovacaoObj->pedido->estabelecimento, "pedido_revisar", $email_send, $variaveis);
				// if($returnEmail['status'] === 'error'){
				// 	return response()->json($returnEmail, 422);
				// }
			}

			$aprovacaoObj->pedido->status_pedido = 20;
			$aprovacaoObj->pedido->motivo_rejeicao = $fields['motivo_rejeicao'];
			$aprovacaoObj->pedido->revisar_mensagem = $fields['mensagem'];

			$historicoPedidoObj = new HistoricoPedido();

			$historicoPedidoObj->pedido = $fields['id'];
			$historicoPedidoObj->natureza = 'revisão';
			$historicoPedidoObj->novo = $fields['motivo_rejeicao'];
			$aprovacaoObj->pedido->cod_usuario_autorizador = $aprovacaoObj->aprovador_id = $historicoPedidoObj->created_by = Auth::id();

			$historicoPedidoObj->save();

			$aprovacaoObj->push();
			$aprovacaoObj->delete();
		} else {
			$EmailObj = new EmailController();
			$email_send = [];
			$email_vendedor = (!empty($aprovacaoObj->pedido->usuario_detalhes->email)) ? $aprovacaoObj->pedido->usuario_detalhes->email : null;
			$email_gerente = (!empty($aprovacaoObj->pedido->usuario_detalhes->supervisor->email)) ? $aprovacaoObj->pedido->usuario_detalhes->supervisor->email : null;
			$email_send = [$email_vendedor, $email_gerente];
			$nome_cliente = '';
			$nome_cliente = $cliente->nome;
			if (!empty($email_send)) {
				$variaveis = [
					'nome_cliente' => $nome_cliente,
					'numero_pedido' => $aprovacaoObj->pedido->id,
					'motivo_recusa' => $fields['motivo_rejeicao']
				];
				$returnEmail = $EmailObj->sendEmailToken($aprovacaoObj->pedido->estabelecimento, "pedido_recusado", $email_send, $variaveis);
				// if($returnEmail['status'] === 'error'){
				// 	return response()->json($returnEmail, 422);
				// }
			}

			$aprovacaoObj->pedido->status_pedido = 5;
			$aprovacaoObj->pedido->motivo_rejeicao = $fields['motivo_rejeicao'];

			$historicoPedidoObj = new HistoricoPedido();

			$historicoPedidoObj->pedido = $fields['id'];
			$historicoPedidoObj->natureza = 'recusa';
			$historicoPedidoObj->novo = $fields['motivo_rejeicao'];
			$aprovacaoObj->pedido->cod_usuario_autorizador = $aprovacaoObj->aprovador_id = $historicoPedidoObj->created_by = Auth::id();

			$historicoPedidoObj->save();

			$aprovacaoObj->push();
			$aprovacaoObj->delete();
		}

		return response()->json([], 200);
	}

	public function modal(Request $request)
	{

		$fields = $request->only('pedido_id');

		$AprovacaoDePedidoObj =  AprovacaoDePedido::with(['pedido', 'pedido.cliente', 'pedido.condicao_pagamento_detalhes', 'pedido.itens_pedido', 'pedido.itens_pedido.precos', 'pedido.itens_pedido.especificacoes', 'pedido.itens_pedido.especificacoes', 'nivelaprovacao', 'nivelaprovacaoPreco', 'pedido.detalhesProjeto', 'pedido.detalhesProjeto.itens'])->findOrFail($fields['pedido_id']);

		$pedidoObj = $AprovacaoDePedidoObj->pedido;

		$parametrosObj = ParametrosAprovacaoPedido::where('estabelecimento', str_pad($pedidoObj->estabelecimento, 2, '0', STR_PAD_LEFT))
			->first();

		$precos_aprovados = 'Todos aprovados';

		$mostrar_botao = false;


		$razao_cnpj_textil = '06311274';

		$raiz_cnpj = !empty($pedidoObj->cliente) ? str_replace([' ', '-', '/', '.'], '', $pedidoObj->cliente->cpf_cnpj) : '';
		$raiz_cnpj = substr($raiz_cnpj, 0, 8);

		$preco_custo = false;
		if (
			!in_array(str_pad($pedidoObj->estabelecimento, 2, '0', STR_PAD_LEFT), ['01', '02']) &&
			$razao_cnpj_textil === $raiz_cnpj
		) {
			$preco_custo = true;
		}

		$condicao_pagamento = ($pedidoObj->condicao_pagamento_detalhes->descricao) ?? '';
		if ($pedidoObj->cartao === true) {
			$condicao_pagamento .= ' - ';
			if ($pedidoObj->presencial === true) {
				$condicao_pagamento .= strtoupper('Presencial');
			} else {
				$condicao_pagamento .= strtoupper('A distÂncia');
			}
		}
		if (
			$AprovacaoDePedidoObj->credito === true
		) {
			if (
				empty($AprovacaoDePedidoObj->aprovacao_credito_user_id) &&
				strtolower(Auth::user()->tipo_usuario->nome) === 'credito'
			) {
				$mostrar_botao = true;
			}
			if (
				$AprovacaoDePedidoObj->preco === true &&
				empty($AprovacaoDePedidoObj->aprovacao_preco_user_id) &&
				(Auth::user()->tipo_usuario->nivel < $AprovacaoDePedidoObj->nivelaprovacaoPreco->id &&
					strtolower(Auth::user()->tipo_usuario->nome) !== 'credito'
				)
			) {
				$mostrar_botao = true;
			}
		} else {
			if (Auth::user()->tipo_usuario->nivel < $AprovacaoDePedidoObj->nivelaprovacao->id) {
				$mostrar_botao = true;
			}
		}

		if (strtolower(Auth::user()->tipo_usuario->nome) == 'administrador') {
			$mostrar_botao = true;
		}

		$check_limite_credito = true;
		$check_data_limite_credito = true;
		$data_limite_credito = '';

		$cpf_cnpj = !empty($pedidoObj->cliente) ? $pedidoObj->cliente->cpf_cnpj : '';
		$raiz_cnpj = $cpf_cnpj;

		if (
			!in_array($pedidoObj->cliente->codigo, $this->codigo_cliente_balcao)
		) {

			if (strlen($raiz_cnpj) == 18) {
				$raiz_cnpj = substr($raiz_cnpj, 0, 10);
			}

			$grupoEmpresarialObj = GrupoEmpresarial::with('participantes')
				->where('raiz_cnpj', $raiz_cnpj)
				->orWhereHas('participantes', function ($query) use ($raiz_cnpj) {
					$query->where('raiz_cnpj', $raiz_cnpj);
				})->first();

			$clientesNasajonQuery = ClienteNasajon::query();

			if (!is_null($grupoEmpresarialObj)) {
				$clientesNasajonQuery->where(function ($query) use ($grupoEmpresarialObj) {
					if (isset($grupoEmpresarialObj->participantes)) {
						foreach ($grupoEmpresarialObj->participantes as $participante) {
							$query->orWhere('cpf_cnpj', 'like', $participante->raiz_cnpj . '%');
						}
						$grupo[] = $participante->raiz_cnpj;
					}

					$query->orWhere('cpf_cnpj', 'like', $grupoEmpresarialObj->raiz_cnpj . '%');
				});

				$grupo = array_merge([$grupoEmpresarialObj->raiz_cnpj], $grupoEmpresarialObj->participantes->pluck('raiz_cnpj')->toArray());
			} else {
				$clientesNasajonQuery->where('cpf_cnpj', 'like', $raiz_cnpj . '%');
				$grupo = [$raiz_cnpj];
			}

			$clientesNasajon = $clientesNasajonQuery->get()->toArray();
			unset($clientesNasajonQuery);
			$ids = [];
			$codcads = [];
			foreach ($clientesNasajon as $key => $value) {
				$codcads[] = $value["codigo"];
				$cnpjs[] = $value["cpf_cnpj"];
				$ids[] = $value['id'];
			}
			unset($clientesNasajon);

			$limite_credito = 0;

			$titulosNasajon = TitulosEmAbertoNasajon::whereIn('cod_cliente', $codcads)->get();
			$data_duplicatas = $titulosNasajon->min('vencimento');

			if (is_null($data_duplicatas)) {
				$data_duplicatas = date('Y-m-d 00:00:00');
			}

			$ChequesRecebidoObj = ChequesEmAbertoNasajon::whereIn('cod_cliente', $codcads)->get();
			$cheques_aberta_data = $ChequesRecebidoObj->min('data_vencimento');
			if (!is_null($cheques_aberta_data)) {
				if (strtotime($data_duplicatas) > strtotime($cheques_aberta_data)) {
					$data_duplicatas = $cheques_aberta_data;
				}
			}

			$parametro_duplicatas_vencidas_a_mais = intval($parametrosObj->maximo_duplicatas_vencidas);

			$duplicatas_vencidas = [
				"dias" => 0,
				"valor" => 0,
			];


			$menor_data = Carbon::createFromFormat('Y-m-d', substr($data_duplicatas, 0, 10))->setTime(0, 0, 0);
			$data_hoje = Carbon::now()->setTime(0, 0, 0);
			if ($menor_data->lt($data_hoje)) {
				$duplicatas_vencidas['dias'] = Carbon::Now()->diffInDays($menor_data);

				if ($parametro_duplicatas_vencidas_a_mais <= $duplicatas_vencidas['dias']) {
					$duplicatas_vencidas['dias'] = "<div class='falha-validacao'>" . (int) $duplicatas_vencidas['dias'] . '</div>';
				}
			}

			$ClienteCreditoObj = ClienteCredito::whereIn('raiz_cnpj', $grupo)->get();

			if (is_null($ClienteCreditoObj)) {
				$check_limite_credito = false;
				$data_limite_credito = 'Em analise';
			} else {

				$limite_credito = (float) $ClienteCreditoObj->sum('valor');

				$data_atulizacaco_limite = new Carbon($ClienteCreditoObj->min('data_atualizacao'));
				$maximo_de_limite_credito = $parametrosObj->maximo_de_limite_credito;
				$data_atulizacaco_limite->addMonths($maximo_de_limite_credito);
				$data_limite_credito = $data_atulizacaco_limite->format('d/m/Y');
				if (strtotime($data_hoje) > strtotime($data_atulizacaco_limite)) {
					$check_data_limite_credito = false;
				}
			}

			$limite_disponivel = $limite_credito;

			$sql_dados_financeiro = sprintf("SELECT * FROM ns.fn_dadosfinanceiroscliente_portal('%s');", $pedidoObj->cliente->id);
			$dados_financeiro = DB::connection('nasajon')->select($sql_dados_financeiro);
			$dados_financeiro = (array) reset($dados_financeiro);

			$maior_atraso = $dados_financeiro['maioratraso'];
			$ultimo_atraso = $dados_financeiro['diasultimoatraso'];
			$media_atraso = $dados_financeiro['mediaatraso'];


			if (!empty($media_atraso)) {
				$media_atraso_exibicao = $media_atraso . " dias";
			} else {
				$media_atraso_exibicao = '';
			}

			$pedidos_em_aberto_nasjon = PedidosVendaNasajon::query()
				->whereIn('situacao_descricao', ['Em Faturamento', 'Em separação', 'Aberto'])
				->where(function ($query) {
					$query->where('grupodeoperacao', 'VENDA')
						->orWhereNull('grupodeoperacao');
				})
				->where('rascunho', false)
				->whereIn('cliente', $ids)
				->sum('valor');
			$pedidos_em_aberto = (float) $pedidos_em_aberto_nasjon;
			unset($pedidos_em_aberto_nasjon);

			$PedidoPortalEmAberto = PedidoPortal::select('*')
				->whereNotIn('status_pedido', [1, 3, 5, 7])
				->whereIn('cod_cliente', $codcads)
				->where('id', '!=', $pedidoObj->id)
				->get();
			$total_pedidos_em_aberto = 0;
			$PedidoPortalEmAberto->each(function ($pedido) use (&$total_pedidos_em_aberto) {
				if (isset($pedido->valor_total->total)) {
					$total_pedidos_em_aberto += $pedido->valor_total->total;
				}
			});
			unset($PedidoPortalEmAberto);
			$pedidos_em_aberto += (float) $total_pedidos_em_aberto;
			$limite_disponivel -= $pedidos_em_aberto;

			$titulos_faturados = ['' => 0];
			$titulosNasajon->each(function ($item) use (&$titulos_faturados) {
				$key = $item->numero . '' . $item->codigo;
				if (!isset($titulos_faturados[$key])) {
					$titulos_faturados[$key] = floatval($item->saldotitulo);
				}
			});
			$duplicatas_em_aberto = (float) array_sum($titulos_faturados);

			$limite_disponivel	-= $duplicatas_em_aberto;

			$nota_credito = 0;
			$notasCredito = NotasCreditoReceberNasajon::whereIn('cod_cliente', $codcads)
				->get();

			$nota_credito += $notasCredito->sum('valor');

			$limite_disponivel += $nota_credito;

			if (!is_null($ChequesRecebidoObj)) {
				$limite_disponivel -= $ChequesRecebidoObj->sum('valor');
			}

			$pedidosPrePagosObj = PedidosPrePago::with(['pedidoNasajon' => function ($query) {
				$query->where('grupodeoperacao', 'VENDA');
			}, 'pedidoNasajon.nota'])
				->whereHas('pedido', function ($query) use ($codcads) {
					$query->whereIn('cod_cliente', $codcads);
				})
				->get();

			$pedidosPrePagosObj = $pedidosPrePagosObj->filter(function ($value) {
				return !is_null($value->pedidoNasajon) && !is_null($value->pedidoNasajon->nota);
			});

			$valor_total_prepago = $pedidosPrePagosObj->sum('valor') ?? 0;
			$valor_baixado_prepago = $pedidosPrePagosObj->sum('valor_pago') ?? 0;
			$total_pre_pagos = $valor_total_prepago - $valor_baixado_prepago < 0 ? 0 : $valor_total_prepago - $valor_baixado_prepago;

			$ChequesObj = Cheque::whereIn('cliente_cpf_cnpj', $cnpjs)->whereHas('pedidos_prepagos')->where('bom_para', '>', Carbon::Now()->format('Y-m-d'))->where('tipo', 'cheque')->get();

			$chque_pre = $ChequesObj->sum('valor');

			$limite_disponivel -= $total_pre_pagos + $chque_pre;

			$cheques_sem_fundo_lucros_perdas = [];
			$cliente_cheque_sem_fundo_lucros_perdas = count($cheques_sem_fundo_lucros_perdas) > 0 ? 'Sim' : 'Não';
			$cheques_sem_fundo_lucros_negociacao = [];
			$cliente_cheque_sem_fundo_negociacao = count($cheques_sem_fundo_lucros_negociacao) > 0 ? 'Sim' : 'Não';
		} else {
			$limite_credito = 0;
			$maior_atraso = '';
			$ultimo_atraso = '';
			$media_atraso = '';
			$pedidos_em_aberto = 0;
			$media_atraso_exibicao = '';
			$pedidosEmAberto = [];
			$limite_disponivel = 0;
			$cnpjs = [];
			$cliente_cheque_sem_fundo_lucros_perdas = 'Não';
			$cliente_cheque_sem_fundo_negociacao = 'Não';
			$nota_credito = '';
			$total_pre_pagos = 0;
			$duplicatas_vencidas = [
				"dias" => 0,
				"valor" => 0,
			];
		}
		$natop = OperacaoNasajon::where('codigo', $pedidoObj->codigo_operacao)->first();
		switch ($pedidoObj->estabelecimento) {
			case '3':
				$origem = 'RO';
				break;
			case '4':
				$origem = 'TO';
				break;
			default:
				$origem  = 'SP';
				break;
		}
		if ($pedidoObj->rj_x_sp == true) {
			$origem = 'SP';
		}

		$precoObj = new ListagemDePrecosController;
		$parametrosAprovacaoObj = ParametrosAprovacao::where('estabelecimento', str_pad($pedidoObj->estabelecimento, 2, '0', STR_PAD_LEFT))
			->orderBy('tipo_usuario_id', 'asc')
			->first();

		$itens = [];

		$aliquotaObj = AliquotaPreco::where('origem', $origem)->where('estado', $pedidoObj->cliente->uf)->get();

		foreach ($aliquotaObj as $value) {
			if ($value->internacional === true) {
				$aliquota['internacional'] = $value->icms_venda;
			} else if ($value->internacional === false) {
				$aliquota['nacional'] = $value->icms_venda;
			}
		}

		$valor_total_itens = 0;
		$erro_em_preco = false;
		foreach ($pedidoObj->itens_pedido as $item) {

			$preco = floatval($item->preco_unitario);
			if ($pedidoObj->metragem_exata == true && $pedidoObj->estabelecimento != 3) {
				$preco = floatval($item->preco_original);
			}
			unset($arr);
			$produtosEstoque = $item->estoque->where('estabelecimento', str_pad($pedidoObj->estabelecimento, 2, '0', STR_PAD_LEFT));
			if ($preco_custo === false) {
				$arr['origem'] = $origem;
				$arr['produto'] = $item->cod_produto;
				$arr['moeda'] = ($pedidoObj->pedido_futuro === true && intval($pedidoObj->estabelecimento) == 3) ? 'dolar' : 'real';
				$arr['prazo_medio'] = $pedidoObj->condicao_pagamento_detalhes['media'] ?? 0;
				$arr['frete'] = $pedidoObj->frete_preco;
				$arr['estado'] = $pedidoObj->cliente->estado_detalhe['uf'];
				$arr['tipo_cliente'] = ($pedidoObj->cliente->inscricaoestadual == 'ISENTO' ||
					intval($pedidoObj->cliente->indicadorinscricaoestadual) == 2 ||
					intval($pedidoObj->cliente->indicadorinscricaoestadual) == 9
				) ? 'isento' : 'juridico';

				if (in_array($item->especificacoes->procedencia, [0, 3, 4, 5])) {
					$arr['aliquota'] = $aliquota['nacional'];
				} else if (in_array($item->especificacoes->procedencia, [1, 2, 6, 7])) {
					$arr['aliquota'] = $aliquota['internacional'];
				}

				$items = new ListaDePrecosRequest($arr);

				$precos = $precoObj->filter($items, true, false, true, true, false, false, false, false, false);
				if (!is_null($item->coluna_a)) {

					$desconto = $item->coluna_a - $preco;
					$desconto_maximo = $item->coluna_a * ($parametrosAprovacaoObj->percentual_desconto / 100);
					$valor_minimo = $item->coluna_a;

					if (
						$pedidoObj->usuario_detalhes->id != 1 &&
						strpos(strtolower($pedidoObj->usuario_detalhes->tipo_usuario->nome), "vendedor") !== false
					) {
						$valor_minimo = $item->coluna_a;
					}
				} else {
					$desconto = str_replace(",", ".", str_replace('.', '', $precos[0]['coluna_a'])) - $preco;
					$desconto_maximo = str_replace(",", ".", str_replace('.', '', $precos[0]['coluna_a'])) * ($parametrosAprovacaoObj->percentual_desconto / 100);
					$valor_minimo = str_replace(",", ".", str_replace('.', '', $precos[0]['coluna_a']));

					if (
						$pedidoObj->usuario_detalhes->id != 1 &&
						strpos(strtolower($pedidoObj->usuario_detalhes->tipo_usuario->nome), "vendedor") !== false
					) {
						$valor_minimo = str_replace(",", ".", str_replace('.', '', $precos[0]['coluna_a']));
					}

					$desconto = str_replace(",", ".", str_replace('.', '', $precos[0]['coluna_a'])) - $preco;
					$desconto_maximo = str_replace(",", ".", str_replace('.', '', $precos[0]['coluna_a'])) * ($parametrosAprovacaoObj->percentual_desconto / 100);
					$valor_minimo = str_replace(",", ".", str_replace('.', '', $precos[0]['coluna_a']));
				}

				$valor_custo = 0;
				$markup = 0;
				$margem = 0;

				if (!is_null($item->precos)) {
					if ($pedidoObj->pedido_futuro === true && intval($pedidoObj->estabelecimento) == 3) {
						$valor_custo = $item->precos->compra_dolar ?? 0;
					} else {
						$valor_custo = $item->precos->compra_real ?? 0;
					}

					if ($valor_custo != 0) {
						$markup = (($preco - $valor_custo) * 100) / $valor_custo;
						$margem = (($preco - $valor_custo) * 100) / $preco;
					}
				}
				$valor_minimo_mask = $item->token_promocional == 'ultra_black' ? parserValor(parserNumber($precos[0]['coluna_a']) * 0.75) : $precos[0]['coluna_a'];
			} else {
				if ($pedidoObj->pedido_futuro === true && intval($pedidoObj->estabelecimento) == 3) {
					$valor_custo = $item->precos->compra_dolar ?? 0;
				} else {
					$valor_custo = $produtosEstoque->custo;
				}
				$markup = 0;
				$margem = 0;
				$valor_minimo = floatval($produtosEstoque->custo);
				if (empty($valor_minimo)) {
					$valor_minimo = $item->precos->compra_real;
				}
				$valor_minimo_mask = $item->token_promocional == 'ultra_black' ? parserValor($valor_minimo * 0.75) : parserValor($valor_minimo);

				if ($valor_custo != 0) {
					$markup = (($preco - $valor_custo) * 100) / $valor_custo;
					$margem = (($preco - $valor_custo) * 100) / $preco;
				}
			}
			$desconto = 0;
			if ($preco < parserNumber($valor_minimo_mask)) {
				$desconto = ((1 - ($preco / parserNumber($valor_minimo_mask))) * 100);
			}

			$valor_total_itens += round($preco * $item->quantidade, 2);

			$erro_preco = $preco < parserNumber($valor_minimo_mask);
			if ($erro_preco != false) {
				$erro_em_preco = true;
			}

			$valor_minimo_projeto = 0;
			$desconto_projeto = 0;
			if (!empty($pedidoObj->detalhesProjeto)) {
				$valor_minimo_projeto = $pedidoObj->detalhesProjeto->itens->where('codigo_produto', $item->especificacoes->codigo_produto)->first()->custo;

				if ($valor_minimo_projeto > $preco) {
					$desconto_projeto = ((1 - ($preco / $valor_minimo_projeto)) * 100);
				}
			}
			$campanha_informativo = '';

			if (isset($item->campanha)) {
				if ($pedidoObj->usuario_detalhes->tipo_usuario_id == 12) {
					if ($item->tipo_comissao_campanha == 1) {
						$campanha_informativo = 'Comissão ' . str_replace('.', ',', $item->comissao_original) . '%' . ' + ' . parserValor($item->incentivo_campanha) . '% incentivo';
					}
					if ($item->tipo_comissao_campanha == 2) {
						$campanha_informativo = 'Comissão ' . parserValor($item->incentivo_campanha) . '% incentivo';
					}
				}
				if (in_array($pedidoObj->usuario_detalhes->tipo_usuario_id, [16, 13])) {
					if ($item->tipo_comissao_campanha == 1) {
						$campanha_informativo = 'Comissão ' . str_replace('.', ',', $item->comissao_original) . '%' . ' + ' . parserValor($item->incentivo_campanha) . '% incentivo';
					}
					if ($item->tipo_comissao_campanha == 2) {
						$campanha_informativo = 'Comissão ' . parserValor($item->incentivo_campanha) . '% incentivo';
					}
					if (is_null($item->incentivo_campanha)) {
						$campanha_informativo = '';
					}
				}
				if (in_array($pedidoObj->usuario_detalhes->tipo_usuario_id, [14, 19])) {
					if ($item->tipo_comissao_campanha == 1) {
						$campanha_informativo = 'Comissão ' . str_replace('.', ',', $item->comissao_original) . '%' . ' + ' . parserValor($item->incentivo_campanha) . '% incentivo';
					}
					if ($item->tipo_comissao_campanha == 2) {
						$campanha_informativo = 'Comissão ' . parserValor($item->incentivo_campanha) . '% incentivo';
					}
				}
			}
			$itens[] = [
				'grupo' => $item->especificacoes->grupo,
				'codigo' => $item->especificacoes->codigo_produto,
				'descricao' => $item->especificacoes->descricao,
				'marca' => $item->especificacoes->marca,
				'linha' => $item->especificacoes->linha,
				'preco' => parserValor($preco),
				'quantidade' => parserValor($item->quantidade),
				'valor_total' => parserValor($preco * $item->quantidade),
				'comissao' => parserValor($item->comissao) . '% ',
				'desconto' => ($desconto > 0 ? number_format($desconto, 5, ",", ".") : 0) . '%',
				'valor_minimo' => $item->token_promocional == 'ultra_black' ? $valor_minimo_mask . '<a href="#" class="btn-informacao-sem-alinhamento" data-toggle="tooltip" data-placement="top" title="" data-original-title="Valor Promocional Ultra Black." style="color: black;"></a>' : $valor_minimo_mask,
				'custo' => parserValor($valor_custo),
				'margem' => parserValor($margem) . '%',
				'markup' => parserValor($markup) . '%',
				'erro_preco' => $erro_preco,
				'valor_minimo_projeto' => parserValor($valor_minimo_projeto),
				'desconto_projeto' => parserValor($desconto_projeto) . '%',
				'campanha_nome' => isset($item->campanha) ? $item->campanha->nome : '',
				'campanha_informativo' => $campanha_informativo,
				'comissao_tipo' => $item->tipo_comissao_campanha,
				'data_hora' => 'Produto Inserido ' . parserDataEHora($item->created_at)
			];
		}

		$tipo_frete = $pedidoObj->tipo_frete;
		$usuario = $pedidoObj->usuario_detalhes['name'];
		$data_entrega = date("d/m/Y", strtotime($pedidoObj->data_previsao_entrega ?? $pedidoObj->data_pedido));

		$ultima_venda = new DateTime($pedidoObj->cliente['DTULTVND']);

		$inatividade = "desde " .  $ultima_venda->format('d/m/Y');

		if (
			$check_limite_credito === false ||
			$check_data_limite_credito === false
		) {
			$data_limite_credito = "<div class='falha-validacao'>" . $data_limite_credito;
			$data_limite_credito .= "</div>";
		} else {
			$data_limite_credito = $data_limite_credito;
		}

		if (
			(strtolower(Auth::user()->tipo_usuario->nome) === "credito" ||
				strtolower(Auth::user()->tipo_usuario->nome) === "administrador"
			)
		) {
			$data_limite_credito .= '&nbsp;<input type="button" value="Revisar crédito" class="btn btn-primary btn-xs" id="btn_add_credito" onclick="addCredito(this)" />';
		}


		if (
			$limite_credito <= 0 &&
			(
				(isset($pedidoObj->cliente->codigo) && !in_array($pedidoObj->cliente->codigo, $this->codigo_cliente_balcao))
			)
		) {
			$limite_credito = "<div class='falha-validacao'>" . parserValor($limite_credito) . "</div>";
		} else {
			$limite_credito = parserValor($limite_credito);
		}

		if ($erro_em_preco == true) {
			$precos_aprovados = "<div class='falha-validacao'>Há pendências</div>";
		}

		if (
			$limite_disponivel < $pedidoObj->valor_total->total &&
			(
				(isset($pedidoObj->cliente->codigo) && !in_array($pedidoObj->cliente->codigo, $this->codigo_cliente_balcao))
			)
		) {
			$limite_disponivel = "<div class='falha-validacao'>" . parserValor($limite_disponivel) . "</div>";
		} else {
			$limite_disponivel = parserValor($limite_disponivel);
		}
		$erro_integracao = '';
		if ($pedidoObj->status_pedido == 6 && !empty($pedidoObj->erro_integracao)) {
			$erro_integracao = "<div class='falha-validacao'>" . $pedidoObj->erro_integracao . "</div>";
		}

		if ($pedidoObj->valor_desconto > 0) {
			$desconto_em_nota = "<div class='falha-validacao'>" . parserValor($pedidoObj->valor_desconto) . '</div>';
		} else {
			$desconto_em_nota = null;
		}

		$prazo_pedido = $pedidoObj->condicao_pagamento_detalhes['media'] ?? 0;
		if (intval($prazo_pedido) > 120) {
			$prazo_pedido = "<div class='falha-validacao'>" . $prazo_pedido . '</div>';
		}

		$duplicatas_em_aberto_return = 0;
		if (!empty($duplicatas_em_aberto)) {
			$duplicatas_em_aberto_return = $duplicatas_em_aberto;
		}

		$show_btn_limite_credito = false;
		if (
			($check_limite_credito !== true ||
				$check_data_limite_credito !== true
			) &&
			(strtolower(Auth::user()->tipo_usuario->nome) === "diretor" ||
				strtolower(Auth::user()->tipo_usuario->nome) === "credito" ||
				strtolower(Auth::user()->tipo_usuario->nome) === "administrador"
			)
		) {
			$show_btn_limite_credito = true;
		}

		$cliente_nome = '';
		$cliente_nome = $pedidoObj->cliente['nome'];
		$tipo_venda = '';
		if ($pedidoObj->rj_x_sp == true) {
			$tipo_venda .= 'Operação RJ/SP - ';
		}
		if (boolval($pedidoObj->pedido_futuro) == true) {
			$tipo_venda .= 'Pedido Futuro';
		} else {
			$tipo_venda .= 'Pronta Entrega';
		}

		$prorrogacao = 'Não';
		if ($AprovacaoDePedidoObj->prorrogacao == true) {
			$prorrogacao = '<div class="falha-validacao">Sim</div>';
		}
		$titulos_prepago = '';
		if ($total_pre_pagos > 0) {
			$titulos_prepago = '<div class="falha-validacao">' . parserValor($total_pre_pagos) . '</div>';
		}

		$campanhas = '';

		$pedidoObj->campanhasPedido->map(function ($item) use (&$campanhas) {
			$campanhas .= $item->campanha->nome . ' - ';
			return $campanhas;
		});

		$return = [
			'cpf_cnpj' => $cpf_cnpj ?? '',
			'pedido' => $pedidoObj->id,
			'id_aprovacao' => $AprovacaoDePedidoObj->id,
			'id_encriptada' => Crypt::encrypt($pedidoObj->cod_cliente),
			'cliente' => $cliente_nome,
			'valor' => parserValor($valor_total_itens),
			'vendedor' => $pedidoObj->usuario_detalhes['codigo_representante'],

			'media_atraso' => $media_atraso_exibicao,
			'maior_atraso' => ($pedidoObj->aprovacao->cliente_com_atraso_e_credito == true) ? '<div class="falha-validacao">' . $maior_atraso . '</div>' : $maior_atraso,
			'inatividade' => $inatividade,
			'limite_credito' => $limite_credito,
			'limite_disponivel' => $limite_disponivel,
			'ultimo_atraso' => $ultimo_atraso,
			'lucros_e_perdas' => $cliente_cheque_sem_fundo_lucros_perdas,
			'negociacao' => $cliente_cheque_sem_fundo_negociacao,
			'notas_credito' => $nota_credito,

			'condicao_pagamento' => ($pedidoObj->aprovacao->cliente_novo_distancia == true) ? '<div class="falha-validacao">' . $condicao_pagamento . '</div>' : $condicao_pagamento,
			'precos' => $precos_aprovados,
			'natureza_operacao' => $pedidoObj->codigo_operacao . ' - ' . $natop->descricao,
			'desconto_em_nota' => $desconto_em_nota,

			'tipo_frete' => parserFrete($tipo_frete),
			'usuario' => $usuario,
			'data_entrega' => $data_entrega,

			'pedidos_em_aberto' => parserValor($pedidos_em_aberto),
			'duplicatas_em_aberto' => parserValor($duplicatas_em_aberto_return + $total_pre_pagos),
			'titulos_prepago' => $titulos_prepago,

			'prazo_adicional' => $parametrosAprovacaoObj->prazo_adicional,
			'prazo_pedido' => $prazo_pedido,
			'itens' => $itens,

			'alerta' => '',

			'criterio_preco' => $pedidoObj->aprovacao['preco'],

			'erro_integracao' => $erro_integracao,

			'duplicatas_vencidas' => $duplicatas_vencidas,

			'preco' => $pedidoObj->frete_preco,
			'cidade_estado' => !empty($cepEnderecoObj) ? $cepEnderecoObj->cidadeBusca->cidade . ' - ' . $pedidoObj->cliente->ESTADO : $pedidoObj->cliente->ESTADO,

			'data_limite_credito' => $data_limite_credito,
			'check_limite_credito' => $check_limite_credito,
			'check_data_limite_credito' => $check_data_limite_credito,
			'show_btn_limite_credito' => $show_btn_limite_credito,
			'mostrar_botao' => $mostrar_botao,
			'tipo_venda' => $tipo_venda,

			'prorrogacao' => $prorrogacao,

			'projeto' => empty($pedidoObj->projeto_id) ? '' : $pedidoObj->projeto_id,
			'campanhas' => !empty($campanhas) ? substr($campanhas, 0, -2) : ''
		];

		return view('programs.aprovacao_pedido.modal')->with(['return' => $return]);
	}

	public static function cancelaPedidosInativos()
	{

		return $pedidos = DB::transaction(function () {

			$pedidosInativos = PedidoPortal::with(
				'itens_pedido',
				'carrinhoCompras',
				'carrinhoCompras.carrinhoCompraItens',
				'carrinhoCompras.dadosClientePedido'
			)
				->where(function ($query) {
					$query->orWhereHas('itens_pedido', function ($query) {
						$query->select(DB::Raw('MAX(pedido_item.updated_at)'));
						$query->havingRaw('MAX(pedido_item.updated_at) < \'' . date("Y-m-d H:i:s", strtotime("-1 hour")) . '\'');
					})
						->orWhereRaw('updated_at < \'' . date("Y-m-d H:i:s", strtotime("-1 hour")) . '\'');
				})
				->whereIn('status_pedido', [1])
				->get();

			$pedidos = [];

			foreach ($pedidosInativos as $pedido) {

				if (isset($pedido->carrinhoCompras)) {
					$usuarioCarrinhoCompras = CarrinhoCompra::where('created_by', $pedido->carrinhoCompras->created_by)
						->where('finalizado', false)
						->count();

					if ($usuarioCarrinhoCompras == 1) {
						$pedido->carrinhoCompras->dadosClientePedido->deleted_by = 1;
						$pedido->carrinhoCompras->dadosClientePedido->save();
						$pedido->carrinhoCompras->dadosClientePedido->delete();
					}
					$pedido->carrinhoCompras->deleted_by = 1;
					$pedido->carrinhoCompras->save();
					$pedido->carrinhoCompras->delete();

					foreach ($pedido->carrinhoCompras->carrinhoCompraItens as $value) {
						$value->deleted_by = 1;
						$value->save();
						$value->delete();
					}
				}

				$pedido->status_pedido = 7;
				$pedido->save();
				$pedidos[] = $pedido->id;
			}

			$data = Carbon::now();
			$data->subHours(48);
			$pedidosInativosPagamento = CieloPedido::with(['pedidoPortal'])
				->where('pago', false)
				->whereNull('pedido_nasajon_id')
				->where('cielo_status_id', 1)
				->where('updated_at', '<', $data)
				->has('pedidoPortal')
				->whereHas('pedidoPortal', function ($query) {
					$query->where('status_pedido', 9);
				})
				->get();

			$pedidosInativosPagamento->each(function ($cielo) {
				if ($cielo->lio == true) {
					$PedidoCieloIntegracaoLioController = new PedidoCieloIntegracaoLioController(new PedidoPortal([]));
					$PedidoCieloIntegracaoLioController->excliurPedido($cielo->id);
				}

				$cielo->pedidoPortal->status_pedido = 7;
				$cielo->pedidoPortal->save();

				$HistoricoPedidoObj = new HistoricoPedido();
				$HistoricoPedidoObj->pedido = $cielo->pedido_id;
				$HistoricoPedidoObj->natureza = 'cancelamento_pagamento_pedido';
				$HistoricoPedidoObj->antigo = 'Pedido cancelado por inatividade de pagamento';
				$HistoricoPedidoObj->created_by = 1;
				$HistoricoPedidoObj->save();

				$cielo->cielo_status_id = 5;
				$cielo->save();
			});

			$pedidoUsarCreditoControllerObj = new PedidoUsarCreditoController;
			$pedidoUsarCreditoControllerObj->cancelamentoPorInatividade();

			$pedidosInativosAprovacaoProposta = PedidoPortal::with('itens_pedido')
				->where(function ($query) {
					$query->orWhereHas('itens_pedido', function ($query) {
						$query->select(DB::Raw('MAX(pedido_item.updated_at)'));
						$query->havingRaw('MAX(pedido_item.updated_at) < \'' . date("Y-m-d H:i:s", strtotime("-24 hour")) . '\'');
					})
						->orWhereRaw('updated_at < \'' . date("Y-m-d H:i:s", strtotime("-24 hour")) . '\'');
				})
				->where('status_pedido', 14)
				->get();

			$pedidos = [];

			foreach ($pedidosInativosAprovacaoProposta as $pedido) {
				$pedido->status_pedido = 7;
				$pedido->save();
				$pedidos[] = $pedido->id;
			}

			$data = Carbon::now();
			$data->subHours(24);

			$pedidosRevisaoInativos = PedidoPortal::where(function ($query) use ($data) {
				$query->orWhereHas('itens_pedido', function ($query) use ($data) {
					$query->select(DB::Raw('MAX(pedido_item.updated_at)'));
					$query->having(DB::Raw('MAX(pedido_item.updated_at)'), '<', $data);
				})
					->orWhere('updated_at',  '<', $data);
			})
				->whereIn('status_pedido', [20])
				->get();

			foreach ($pedidosRevisaoInativos as $pedido) {
				$pedido->status_pedido = 7;
				$pedido->save();
				$pedidos[] = $pedido->id;
			}

			$data = Carbon::now();
			/*
				Mudança do horário solicitado pela Fabíola no chamado https://textilmn.freshdesk.com/a/tickets/19499 de 72 para 48
			*/
			$data->subHours(48);

			$pedidosPropostaRecusada = PedidoPortal::where(function ($query) use ($data) {
				$query->orWhereHas('itens_pedido', function ($query) use ($data) {
					$query->select(DB::Raw('MAX(pedido_item.updated_at)'));
					$query->having(DB::Raw('MAX(pedido_item.updated_at)'), '<', $data);
				})
					->orWhere('updated_at',  '<', $data);
			})
				->whereIn('status_pedido', [15])
				->get();

			foreach ($pedidosPropostaRecusada as $pedido) {
				$pedido->status_pedido = 7;
				$pedido->save();
				$pedidos[] = $pedido->id;
			}

			return $pedidos;
		});
	}

	public static function deletaPedidosCancelados()
	{

		return $pedidos = DB::transaction(function () {

			$pedidosCancelados = PedidoPortal::where('updated_at', "<", date("Y-m-d H:i:s", strtotime("-15 days")))
				->where('status_pedido', 7)
				->get();

			$pedidos = [];

			foreach ($pedidosCancelados as $value) {
				$value->delete();
				$pedidos[] = $value->id;
			}

			$PedidosFuturosCancelarAMais = PedidoPortal::where('status_pedido', 8)
				->where('pedido_futuro', 'true')
				->whereNull('projeto_id')
				->where('data_previsao_entrega', '<', date("Y-m-d", strtotime("-30 days")))
				->get();

			foreach ($PedidosFuturosCancelarAMais as $pedido) {

				$pedido->deleted_by = 1;
				$pedido->save();

				$HistoricoPedidoObj = new HistoricoPedido();
				$HistoricoPedidoObj->pedido = $pedido->id;
				$HistoricoPedidoObj->natureza = 'cancelamento_programado';
				$HistoricoPedidoObj->antigo = 'Pedido cancelado, pois o está a mais de 30 dias depois da chegada';
				$HistoricoPedidoObj->created_by = 1;
				$HistoricoPedidoObj->save();

				$pedido->delete();
				$pedidos[] = $pedido->id;
			}


			return $pedidos;
		});
	}


	public function processaIntegracaoPedidoNasajon(PedidoPortal $Pedido, $fields, $transferencia_esperando_confimracao = false)
	{
		$estabelecimento = str_pad($Pedido->estabelecimento, 2, '0', STR_PAD_LEFT);

		$historicoPedidoObj = new HistoricoPedido();
		$historicoPedidoObj->pedido = $Pedido->id;
		$historicoPedidoObj->novo = '';
		$historicoPedidoObj->created_by = Auth::id();

		if (!in_array($Pedido->status_pedido, [3, 4])) {
			if (
				$Pedido->pedido_futuro === false ||
				(isset($fields['aprovacao_pedido_futuro']) && $fields['aprovacao_pedido_futuro'] == 'true')
			) {

				if (in_array($Pedido->tipo_venda, ['rj_x_sp', 'rj_x_sp_triangular', 'pre_pago_rj_x_sp'])){

					if($Pedido->presencial === false && $Pedido->cartao === true){
						$pedido_online = CieloPedido::where('pedido_id',$Pedido->id)->orderBy('updated_at','desc')->first();
						
						if(empty($pedido_online)){
							$cielo_pedido_online = new PedidoCieloIntegracaoEcommerceController($Pedido);
							return;
						}else{
							if($pedido_online->pago !== true){
								return;
							}
						}
					}

					$Pedido->status_pedido = 4;
					$Pedido->save();

					if (!is_null($Pedido->aprovacao)){
						$Pedido->aprovacao->delete();
					}

					$PedidoRjSpObj = new PedidoRjSp();
					$PedidoRjSpObj->pedido_id = $Pedido->id;
					$PedidoRjSpObj->save();

					$this->atualizarDataPrevisaoEntregaOriginal($Pedido);

					return [
						'status' => 'success',
						'message' => 'O pedido foi aprovado e aguarda pagamento.',
						'error' => [],
						'response' => []
					];
				}
				
				if ($Pedido->presencial == true && $Pedido->cartao == true) {
					$stone_transacao = new StoneTransacaoController;

					try {
						$verifica_integracao_stone = StoneTransacoesPedido::with('retornoTransacaoAvulsa')->where('pedido_id', $Pedido->id)->get();
						if (empty($verifica_integracao_stone->first())) {
							$stone_transacao->enviarPedidoConnect20($Pedido);

							$Pedido->status_pedido = 9;
							$Pedido->save();

							return;
						} else {
							$verifica_pagamento = false;
							foreach ($verifica_integracao_stone as $integracao) {
								if ($integracao->pago === false || $integracao->pago === true) {
									$verifica_pagamento = true;
								}
							}

							if ($verifica_pagamento === false) {
								return;
							}
						}
					} catch (Exception $e) {
						$erro_transacao = new StoneErroTransacoesPedido;
						$erro_transacao->erro_msg = (string)$e->getMessage() . 'Pedido ' . $Pedido->id;
						$erro_transacao->created_by = Auth::user()->id;
						$erro_transacao->stone_cadastro_maquininha_id = 1;
						$erro_transacao->pedido_id = $Pedido->id;
						$erro_transacao->save();

						$EmailObj = new EmailController();
						$email_send = [];
						$variaveis = [
							'erro' => 'Pedido ' . $Pedido->id . ' erro ao enviar transação - ' . (string)$e->getMessage()
						];
						$returnEmail = $EmailObj->sendEmailToken('00', "erro_verifica_transacao_estone", $email_send, $variaveis);

						$erro_transacao = new StoneErroTransacoesPedido;
						$erro_transacao->erro_msg = (string)$e->getMessage();
						$erro_transacao->created_by = Auth::user()->id;
						$erro_transacao->stone_cadastro_maquininha_id = 1;
						$erro_transacao->pedido_id = $Pedido->id;
						$erro_transacao->save();

						$Pedido->status_pedido = 9;
						$Pedido->save();

						return [
							'status' => 'error',
							'message' => 'Stone fora do ar, fazer o processo de pagamento manual!',
							'error' => [],
							'response' => []
						];
					}
				}

				if (
					!in_array(str_replace('.', '', explode('/', $Pedido->cliente->cpf_cnpj)[0]), ['05075884', '06311274']) &&
					$Pedido->cartao == true &&
					!in_array($Pedido->status_pedido, [9, 11])
				) {
					$aprovacaoObj = AprovacaoDePedido::where('pedido_id', $Pedido->id)->first();

					if (!is_null($aprovacaoObj)) {

						$Pedido->cod_usuario_autorizador = Auth::id();
						$Pedido->save();

						$aprovacaoObj->aprovador_id = Auth::id();
						$aprovacaoObj->save();
						$aprovacaoObj->delete();

						$historicoPedidoObj->save();
					} else {

						$aprovacaoObj = new AprovacaoDePedido;

						$aprovacaoObj->pedido_id = $Pedido->id;
						$aprovacaoObj->pedido->cod_usuario_autorizador = 1;
						$aprovacaoObj->aprovador_id = 1;
						$aprovacaoObj->nivel_aprovacao = 1;
						$aprovacaoObj->credito = false;
						$aprovacaoObj->condicao_pagamento = false;
						$aprovacaoObj->preco = false;
						$aprovacaoObj->integracao = false;

						$aprovacaoObj->save();
						$aprovacaoObj->delete();
					}
					$PedidoCieloIntegracaoControllerOjb = new PedidoCieloIntegracaoController($Pedido);

					$this->atualizarDataPrevisaoEntregaOriginal($aprovacaoObj->pedido);

					if ($Pedido->presencial == false) {
						return [
							'status' => 'success',
							'message' => 'O pedido foi aprovado e aguarda pagamento.',
							'error' => [],
							'response' => []
						];
					}
				}

				$Pedido->status_pedido = 4;
				$Pedido->save();

				$Cliente = $Pedido['cliente'];
				$ClienteNasajonObj = ClienteNasajon::where('codigo', $Cliente->codigo)->where('bloqueado', 'false')->first();
				$cliente_uuid = "'" . $ClienteNasajonObj->id . "'::uuid";

				$cliente_conta_e_ordem_uuid = 'null';
				$ClienteContaEOrdem = $Pedido['cliente_conta_e_ordem'];
				if (isset($ClienteContaEOrdem)) {
					$cliente_conta_e_ordem_uuid = "'" . $ClienteContaEOrdem->id . "'";
				}
				try {
					$condicao_pagamento = $Pedido['condicao_pagamento_detalhes'];
					$formapagamento_uuid = empty($condicao_pagamento['nasajon_forma_pagamento']) ? 'null' : "'" . $condicao_pagamento['nasajon_forma_pagamento'] . "'";
					$parcelamento_uuid = empty($condicao_pagamento['nasajon_parcela']) ? 'null' : "'" . $condicao_pagamento['nasajon_parcela'] . "'";

					$transportadora_uuid = "'" . $Pedido['detalhesTransportador']->id . "'";

					$transportadora_redespacho_uuid = 'NULL';
					if (!empty($Pedido['detalhesTransportadorRedespacho'])) {
						$transportadora_redespacho_uuid = "'" . $Pedido['detalhesTransportadorRedespacho']->id . "'";
					}
					$valor_total = $Pedido['valor_total']->total;
					if (in_array($Pedido->tipo_venda, $this->tipo_vendas_prepago)) {
						$valor_total = ($valor_total / 2);
					}
					$desconto = floatval($Pedido->valor_desconto);
					$tipo_frete = '';
				} catch (Exception $e) {
					dd($Pedido);
				}

				/**
				 * PorContaDoEmitente = 0,
				 * PorContaDoDestinatario = 1,
				 * PorContaDeTerceiros = 2,
				 * SemFrete = 3,
				 * ProprioPorContaRemetente = 4,
				 * ProprioPorContaDestinatario = 5
				 **/
				/**
				 * 'P' => "PAGO - CIF",
				 * 'A' => "A PAGAR - FOB",
				 * 'C' => "COBRADO - FOB",
				 * 'T' => "TERCEIRO - FOB",
				 * 'S' => "SEM FRETE - FOB"
				 */
				switch ($Pedido->tipo_frete) {
					case 'A':
						$tipo_frete = '1';
						break;
					case 'P':
						$tipo_frete = '0';
						break;
					case 'S':
						$tipo_frete = '3';
						break;
					case 'T':
						$tipo_frete = '2';
						break;
					default:
						$tipo_frete = '0';
						break;
				}
				if (strtoupper($Pedido['detalhesTransportador']->nome) == 'RETIRA') {
					$tipo_frete = '4';
				}

				$usuario_cadastro_uuid = UserNajason::where('nome', 'Mestre')->first()->usuario;
				$operacao = '';
				$codigo_operacao = $this->getCodigoOperacao($Pedido);
				if (
					in_array($estabelecimento, ['01', '02']) &&
					in_array(str_replace(".", "", (str_replace(",", "", (str_replace("/", "", (str_replace(".", "", str_replace("-", "", $ClienteNasajonObj->cpf_cnpj)))))))), ['06311274000269', '06311274000340'])
				) {
					$ClienteNasajonObj = ClienteNasajon::where(DB::raw("replace(replace(replace(cpf_cnpj, '.', ''), '-', ''), '/', '')"), '97544848000202')->where('bloqueado', 'false')->first();
					$cliente_conta_e_ordem_uuid = "'" . $ClienteNasajonObj->id . "'";
					$codigo_operacao = 'PEDTRIANGULAR';
				}

				$operacao = OperacaoNasajon::where('codigo', $codigo_operacao)->first()->operacao;
				$operacao = "'" . $operacao . "'";

				$vendedor = $Pedido->usuario_detalhes->vendedor_nasajon;
				$vendedor = "'" . $vendedor->id . "'";
				$observacao = remove_emoji(str_replace("'", " ", $Pedido->observacao));

				if (!empty($observacao)) {
					$observacao = mb_convert_encoding(utf8_decode($observacao), "UTF-8", "Windows-1252");
				}

				$valor_frete = floatval($Pedido->valor_frete);

				$tipooperacao = '23';
				$numero_pedido_cliente = !empty($Pedido->no_pedido_compra) ? $Pedido->no_pedido_compra : '';
				$indicador_pagamento = '1'; // 0 = a vista | 1 = a prazo
				$modo_compra = '2';
				$comissao = 0;
				$valor_total = 0;
				foreach ($Pedido->itens_pedido as $item) {
					$comissao += ($item->quantidade * $item->preco_unitario) * ($item->comissao / 100);
					$valor_total += ($item->quantidade * $item->preco_unitario);
				}
				$porcentagem_comissao = (float) (($comissao) / floatval($valor_total)) * 100;
				$cfop = $this->getCFOPIntegracao($Pedido);

				$data_pedido = date('Y-m-d');
				if (!empty($Pedido->data_previsao_entrega)) {
					$data_pedido = date('Y-m-d', strtotime($Pedido->data_previsao_entrega));
				}

				$observacao_nota = $this->getMensagemNotaNasajon($Pedido, $codigo_operacao);

				if (in_array($codigo_operacao, ["PEDIDOTRANSF", "PEDIDOTRANSFSEMICMS", "PEDIDOTRANSFTEXTIL", "PEDIDOTRANSFTOROSP", "PEDTRANSFCOMREMESSA", "PEDIDOFUTTORO", "SIMPLESFATFUTURA", "PEDIDORETVENDAFORA"])) {
					$formapagamento_uuid = "null";
					$parcelamento_uuid = "null";
				}
				if (
					!empty($cliente_conta_e_ordem_uuid) &&
					in_array(str_replace(".", "", (str_replace(",", "", (str_replace("/", "", (str_replace(".", "", str_replace("-", "", $ClienteNasajonObj->cpf_cnpj)))))))), ['06311274000269', '06311274000340'])
				) {
					$ArmazenObj = NasajonEstabelecimento::where('codigo', '20')->first();
					$cliente_conta_e_ordem_uuid = "'" . $ArmazenObj->id_pessoa . "'";
				}

				$sql_api_insercao = "select * from integracoes.api_pedidovendanovo (\n" .
					"uuid_generate_v4(),/* pedido chave*/\n" .
					"current_date,/* data */\n" .
					"(select estabelecimento from ns.estabelecimentos where codigo = '{$estabelecimento}'),/* estabelecimento */\n" .
					"{$cliente_uuid},/* cliente */\n" .
					"{$vendedor},/* vendedor */\n" .
					"'{$observacao}',/* observacao */\n" .
					"{$formapagamento_uuid},/* forma pagamento */\n" .
					"{$parcelamento_uuid},/* parcelamento */\n" .
					"{$valor_total},/* valor total */\n" .
					"{$desconto},/* desconto */\n" .
					"{$transportadora_uuid},/* transportador */\n" .
					"{$transportadora_redespacho_uuid},/* transportador redespacho */\n" .
