					"{$operacao}, /* operacao */\n" .
					"{$porcentagem_comissao}, /* comissão vendedor */\n" .
					"'{$data_pedido}',/* data de entrega */\n" .
					"'{$observacao_nota}'/* observacao da nota */\n" .
					");";

				try {
