					"{$formapagamento_uuid},\n" .
					"{$parcelamento_uuid},\n" .
					"{$valor_total},\n" .
					"{$desconto},\n" .
					"{$transportadora_uuid},\n" .
					"{$transportadora_redespacho_uuid},\n" .
					"{$tipo_frete},\n" .
					"{$valor_frete},\n" .
					"'{$usuario_cadastro_uuid}',\n" .
					"{$indicador_pagamento},\n" .
					"'{$cfop}',\n" .
					"{$tipooperacao},\n" .
					"'{$numero_pedido_cliente}',\n" .
					"{$modo_compra},\n" .
					"{$cliente_conta_e_ordem_uuid},\n" .
					"{$operacao},\n" .
					"{$porcentagem_comissao},\n" .
