				try {
					$insert_nasajon = DB::connection('nasajon')->select($sql_api_insercao);
				}catch(\Exception $e){
					$EmailObj = new EmailController();
					$email_send = [];
					$variaveis = [
						'erro' => 'Pedido '.$Pedido->id.' erro ao integrar pedido com a nasajon- '.(string)$e->getMessage()
					];
					$returnEmail = $EmailObj->sendEmailToken('00', "erro_verifica_transacao_estone", $email_send, $variaveis);
					
					return [
						'status' => 'error',
						'message' => 'Ocorreu uma instabilidade contate o setor responsavel!',
						'error' => [$e, $sql_api_insercao],
						'response' => []
					];
				}

				$mensagem_nasajon = $insert_nasajon[0]->mensagem;
				$mensagem_nasajon = json_decode($mensagem_nasajon, true);
				if ($mensagem_nasajon['codigo'] !== 'OK') {
					$this->processaErroIntegracaoPedidoNasajon($Pedido, $mensagem_nasajon['mensagem'], $pedido_uuid);

					return [
						'status' => 'error',
						'message' => 'Ocorreu uma instabilidade contate o setor responsavel!',
						'error' => [$mensagem_nasajon['mensagem'], $sql_api_insercao],
						'response' => []
