						'" . $pedido_uuid . "',
						'" . $agente_venda . "',
						'100',
						'" . $porcentagem_comissao . "',
						false
					)";

					try {
						$insert_nasajon = DB::connection('nasajon')->select($sql_api_agente_venda);
