					$sql_api_validacao = "select * from integracoes.bloquear_pedido('" . $pedido_uuid . "')";
					try {
						$insert_nasajon = DB::connection('nasajon')->select($sql_api_validacao);
					} catch (\Exception $e) {
						return [
							'status' => 'error',
							'message' => 'Ocorreu uma instabilidade contate o setor responsavel!',
