					if (empty($verificar_pedido_gerado->pedido_gerado)) {
						$insert_nasajon = DB::connection('nasajon')->select($sql_api_validacao);
					} else {
						return [
							'status' => 'error',
							'message' => 'Pedido já foi gerado!',
							'error' => [],
							'response' => []
						];
					}
				} catch (\Exception $e) {
					$this->processaErroIntegracaoPedidoNasajon($Pedido, 'Erro ao enviar pedido para processar na Nasajon' . $e->getMessage(), $pedido_uuid);
					$Pedido->status_pedido = 6;
					$Pedido->erro_integracao = $e->getMessage();
					$Pedido->updated_by = 1;
					$Pedido->updated_at = date("Y-m-d H:i:s");
					$Pedido->save();
					return [
						'status' => 'error',
						'message' => 'Ocorreu uma instabilidade contate o setor responsavel!',
						'error' => $e,
						'response' => []
					];
				}
				$mensagem_nasajon = json_decode($insert_nasajon[0]->mensagem, true);
				if ($mensagem_nasajon['codigo'] !== 'OK') {
					$this->processaErroIntegracaoPedidoNasajon($Pedido, $mensagem_nasajon['mensagem'], $pedido_uuid);
					return [
						'status' => 'error',
						'message' => 'Ocorreu uma instabilidade contate o setor responsavel!',
						'error' => [$mensagem_nasajon['mensagem']],
						'response' => []
					];
				}
				$historicoPedidoObj->natureza = 'Aprovação de pedido';

				$codigo_pedido = $PedidosVendaNasajonObj->numero;
				$Pedido->pedido_gerado = $codigo_pedido;
				$Pedido->codigo_operacao = $codigo_operacao;
				$Pedido->status_pedido = 3;

				$Pedido->load('aprovacao');

				if (!is_null($Pedido->aprovacao)) {
					$Pedido->aprovacao->delete();
				}

				$Pedido->save();

				if (in_array($Pedido->tipo_venda, $this->tipo_vendas_prepago)) {
					$PedidosPrePagoObj = new PedidosPrePago();
					$PedidosPrePagoObj->pedido_id = $Pedido->id;
					$PedidosPrePagoObj->pedido_nasajon_id = $PedidosVendaNasajonObj->id;
					$PedidosPrePagoObj->pedido_nasajon_numero = $PedidosVendaNasajonObj->numero;
					$PedidosPrePagoObj->valor = $PedidosVendaNasajonObj->valor;
					$PedidosPrePagoObj->created_by = Auth::id() ?? 1;
					$PedidosPrePagoObj->save();
				}

				$this->enviarEmail($Pedido);
				$this->checkPedidoMonitorAprovado($Pedido, Auth::id());
			} else {

				$historicoPedidoObj->natureza = 'pedido futuro';
				$historicoPedidoObj->novo = "Aprovado como pedido programado - Entrega prevista para " . $Pedido->data_previsao_entrega;
				$historicoPedidoObj->save();

				if (in_array($Pedido->tipo_venda, ['rj_x_sp_futuro', 'rj_x_sp_triangular', 'pre_pago_rj_x_sp'])) {
					if (!is_null($Pedido->aprovacao)) {
						$Pedido->aprovacao->delete();
					}
				}

				$Pedido->status_pedido = 8;
				$Pedido->cod_usuario_autorizador = Auth::id();
				$Pedido->save();
			}

			$historicoPedidoObj->save();

			$Pedido->updated_by = Auth::id();
			$Pedido->save();

			$aprovacaoObj = AprovacaoDePedido::where('pedido_id', $Pedido->id)->first();

			if (!is_null($aprovacaoObj)) {

				$Pedido->cod_usuario_autorizador = Auth::id();
				$Pedido->save();

				$aprovacaoObj->aprovador_id = Auth::id();
				$aprovacaoObj->save();
				$aprovacaoObj->delete();

				$historicoPedidoObj->save();
			} else {

				$aprovacaoObj = new AprovacaoDePedido;

				$aprovacaoObj->pedido_id = $Pedido->id;
				$aprovacaoObj->pedido->cod_usuario_autorizador = 1;
				$aprovacaoObj->aprovador_id = 1;
				$aprovacaoObj->nivel_aprovacao = 1;
				$aprovacaoObj->credito = false;
				$aprovacaoObj->condicao_pagamento = false;
				$aprovacaoObj->preco = false;
				$aprovacaoObj->integracao = false;

				$aprovacaoObj->save();
				$aprovacaoObj->delete();
			}
		}
	}

	private function processaErroIntegracaoPedidoNasajon(PedidoPortal $Pedido, $mensagem, $id_nasajon = null)
	{

		$historicoPedidoObj = new HistoricoPedido();
		$historicoPedidoObj->pedido = $Pedido->id;
		$historicoPedidoObj->natureza = 'integracao_nasajon';
		$historicoPedidoObj->novo = 'Erro ao importar pedido: ' . $mensagem;
		$historicoPedidoObj->created_by = Auth::id();
		$historicoPedidoObj->save();

		$Pedido->status_pedido = 6;
		$Pedido->erro_integracao = $mensagem;
		$Pedido->updated_by = 1;
		$Pedido->updated_at = date("Y-m-d H:i:s");
		$Pedido->save();

		if ($id_nasajon !== null) {
			$result = DB::connection('nasajon')->select("SELECT * from integracoes.api_pedido_cancelar('" . $id_nasajon . "')");

			if (!is_array($result) || sizeof($result) == 0) {
				$response = [
					"status" => 'error',
					"message" => 'Ocorreu uma instabilidad, contate o setor responsavel!',
					"error" => [],
					"response" => [$result]
				];

				return response()->json($response, 422);
			}
		}

		$aprovacaoObj = AprovacaoDePedido::where('pedido_id', $Pedido->id)->get()->first();

		if (!is_null($aprovacaoObj)) {
			$aprovacaoObj->integracao = true;
			$aprovacaoObj->save();
		} else {
			$aprovacaoObj = new AprovacaoDePedido;
			$aprovacaoObj->pedido_id = $Pedido->id;
			$aprovacaoObj->pedido->cod_usuario_autorizador = 1;
			$aprovacaoObj->aprovador_id = 1;
			$aprovacaoObj->nivel_aprovacao = 1;
			$aprovacaoObj->credito = false;
			$aprovacaoObj->condicao_pagamento = false;
			$aprovacaoObj->preco = false;
			$aprovacaoObj->integracao = true;
			$aprovacaoObj->save();
		}
	}

	private function getCFOPIntegracao(PedidoPortal $Pedido)
	{
		$cfop = '';

		if (in_array(str_replace('.', '', explode('/', $Pedido->cliente->cpf_cnpj)[0]), ['05075884', '06311274'])) {
			if ($Pedido->estabelecimentoDetalhes->raizcnpj == str_replace('.', '', explode('/', $Pedido->cliente->cpf_cnpj)[0])) {
				if (in_array($Pedido->estabelecimento, [3, 4])) {

					if ($Pedido->cliente->uf == $Pedido->estabelecimentoDetalhes->endereco->cidadeBusca->uf) {
						$cfop = '5156';
					} else {
						$cfop = '6156';
					}
				} else {
					if ($Pedido->cliente->uf == $Pedido->estabelecimentoDetalhes->endereco->cidadeBusca->uf) {
						$cfop = '5152';
					} else {
						$cfop = '6152';
					}
				}
			} else {
				if ($Pedido->cliente->uf == $Pedido->estabelecimentoDetalhes->endereco->cidadeBusca->uf) {
					$cfop = '5119';
				} else {
					$cfop = '6119';
				}
			}
		} else {
			if ($Pedido->tipo_venda === 'pedido_pilotagem') {
				if ($Pedido->cliente->uf == $Pedido->estabelecimentoDetalhes->endereco->cidadeBusca->uf) {
					$cfop = '5911';
				} else {
					$cfop = '6911';
				}
			} else {
				$naturezaOperacaoObj = NaturezaDeOperacaoNasajon::where('estabelecimento', intval($Pedido->estabelecimento))
					->where('estado_destino', $Pedido->cliente['uf'])
					->get()
					->first();

				if ($Pedido->tipo_venda == 'venda' || $Pedido->tipo_venda == 'pre_pago' || $Pedido->tipo_venda == 'producao' || $Pedido->tipo_venda == 'pronta_entrega_venda' || $Pedido->tipo_venda == 'pedido_futuro_venda' || $Pedido->tipo_venda == 'pre_pago_futuro' || $Pedido->tipo_venda == 'remessa_faturamento') {
					if (!empty($Pedido->cliente->suframa_codigo) && !in_array($Pedido->estabelecimento, [3, 4]) && in_array($Pedido->cliente->uf, ['RO', 'RR', 'AP', 'AC', 'AM'])) {
						if ($Pedido->tipo_venda === 'triangular' || $Pedido->tipo_venda == 'pronta_entrega_triangular' || $Pedido->tipo_venda == 'pedido_futuro_triangular' || $Pedido->tipo_venda == 'pre_pago_triangular' || $Pedido->tipo_venda == 'producao_triangular') {
							$cfop = '6123';
						} else if (
							$Pedido->cliente->inscricaoestadual === 'ISENTO' ||
							intval($Pedido->cliente->indicadorinscricaoestadual) === 2 ||
							intval($Pedido->cliente->indicadorinscricaoestadual) === 9
						) {
							$cfop = '6108';
						} else {
							$cfop = '6106';
						}
					} else if (
						$Pedido->cliente->inscricaoestadual !== 'ISENTO' &&
						intval($Pedido->cliente->indicadorinscricaoestadual) !== 2 &&
						intval($Pedido->cliente->indicadorinscricaoestadual) !== 9
					) {
						$cfop = $naturezaOperacaoObj->nat_op_pj;
					} else {
						$cfop = $naturezaOperacaoObj->nat_op_pf;
					}
				} else if ($Pedido->tipo_venda == 'triangular' || $Pedido->tipo_venda == 'pronta_entrega_triangular' || $Pedido->tipo_venda == 'pedido_futuro_triangular' || $Pedido->tipo_venda == 'pre_pago_triangular') {
					if ($Pedido->cliente->uf == $Pedido->estabelecimentoDetalhes->endereco->cidadeBusca->uf) {
						if (!empty($Pedido->cliente->clienteIndustrializacaoContaOrdem)) {
							$cfop = '5123';
						} else {
							$cfop = '5120';
						}
					} else {
						if (!empty($Pedido->cliente->clienteIndustrializacaoContaOrdem)) {
							$cfop = '6123';
						} else {
							$cfop = '6120';
						}
					}
				} else if ($Pedido->tipo_venda == 'isento') {
					$cfop = $naturezaOperacaoObj->nat_op_pf;
				}
			}
		}
		return $cfop;
	}

	public function getCodigoOperacao(PedidoPortal $Pedido)
	{
		if (in_array(str_replace('.', '', explode('/', $Pedido->cliente->cpf_cnpj)[0]), ['05075884', '06311274'])) {
			if ($Pedido->estabelecimentoDetalhes->raizcnpj == str_replace('.', '', explode('/', $Pedido->cliente->cpf_cnpj)[0])) {
				if (in_array($Pedido->estabelecimento, [3, 4]) && in_array(str_replace('.', '', str_replace('/', '', str_replace('-', '', $Pedido->cliente->cpf_cnpj))), ['06311274000269', '06311274000340'])) {
					$codigo_operacao = 'PEDIDOTRANSFSEMICMS';
				} else if (in_array($Pedido->estabelecimento, [3, 4]) && !in_array(str_replace('.', '', str_replace('/', '', str_replace('-', '', $Pedido->cliente->cpf_cnpj))), ['06311274000269', '06311274000340'])) {
					$codigo_operacao = 'PEDIDOTRANSFTOROSP';
				} else if (!in_array($Pedido->estabelecimento, [3, 4]) && in_array(str_replace('.', '', str_replace('/', '', str_replace('-', '', $Pedido->cliente->cpf_cnpj))), ['06311274000269', '06311274000340'])) {
					$codigo_operacao = 'PEDTRANSFCOMREMESSA';
				} else if ($Pedido->tipo_venda === 'producao' || $Pedido->tipo_venda === 'producao_triangular') {
					$codigo_operacao = 'PEDIDOVENDA';
				} else {
					$codigo_operacao = 'PEDIDOTRANSF';
				}
			} else {
				if (in_array($Pedido->estabelecimento, [3, 4])) {
					$codigo_operacao = 'PEDVENDATORO';
				} else if ($Pedido->tipo_venda === 'producao' || $Pedido->tipo_venda === 'producao_triangular') {
					$codigo_operacao = 'PEDIDOVENDA';
				} else {
					$codigo_operacao = 'PEDIDOVENDA';
				}
			}
		} else {

			$codigo_operacao = 'PEDIDOVENDA';
			if (in_array($Pedido->estabelecimento, [3, 4])) {
				if (!empty($Pedido->cliente->suframa_codigo) && in_array($Pedido->cliente->uf, ['RO', 'RR', 'AP', 'AC', 'AM'])) {
					if ($Pedido->tipo_venda === 'pedido_pilotagem') {
						$codigo_operacao = 'PEDAMOSTRAGRATISZFM';
					} else if (
						$Pedido->cliente->inscricaoestadual === 'ISENTO' ||
						intval($Pedido->cliente->indicadorinscricaoestadual) === 2 ||
						intval($Pedido->cliente->indicadorinscricaoestadual) === 9
					) {
						$codigo_operacao = 'PEDVENDAZFMTOROISENCON';
					} else if ($Pedido->tipo_venda === 'triangular' || $Pedido->tipo_venda == 'pronta_entrega_triangular' || $Pedido->tipo_venda == 'pedido_futuro_triangular' || $Pedido->tipo_venda == 'pre_pago_triangular') {
						$codigo_operacao = 'PEDVENDAORDEMTOROZFM';
					} else {
						$codigo_operacao = 'PEDVENDAZFMTORO';
					}
				} else if ($Pedido->tipo_venda === 'pedido_pilotagem') {
					$codigo_operacao = 'PEDAMOSTRAGRATIS';
				} else if ($Pedido->tipo_venda === 'pedido_orgaopublico') {
					$codigo_operacao = 'PEDIDOPUBLICOTORO';
				} else if ($Pedido->tipo_venda === 'remessa_faturamento') {
					$codigo_operacao = 'PEDIDOFUTTORO';
				} else if ($Pedido->tipo_venda === 'triangular' || $Pedido->tipo_venda == 'pronta_entrega_triangular' || $Pedido->tipo_venda == 'pedido_futuro_triangular' || $Pedido->tipo_venda == 'pre_pago_triangular') {
					$codigo_operacao = 'PEDVENDAORDEMTORO';
				} else if (
					$Pedido->cliente->inscricaoestadual === 'ISENTO' ||
					(intval($Pedido->cliente->indicadorinscricaoestadual) === 2 ||
						intval($Pedido->cliente->indicadorinscricaoestadual) === 9
					)
				) {
					$codigo_operacao = 'PEDIDOISENTOTORO';
				} else {
					$codigo_operacao = 'PEDVENDATORO';
				}
			} else if ($Pedido->tipo_venda === 'pedido_orgaopublico') {
				$codigo_operacao = 'PEDIDOPUBLICOSP';
			} else if ($Pedido->tipo_venda === 'pedido_pilotagem') {
				$codigo_operacao = 'PEDAMOSTRA';
			} else if ($Pedido->tipo_venda === 'remessa_faturamento') {
				$codigo_operacao = 'SIMPLESFATFUTURA';
			} else if ($Pedido->tipo_venda === 'venda' || $Pedido->tipo_venda == 'pre_pago' || $Pedido->tipo_venda == 'pronta_entrega_venda' || $Pedido->tipo_venda == 'pedido_futuro_venda' || $Pedido->tipo_venda == 'pre_pago_futuro' || $Pedido->tipo_venda == 'pre_pago_producao' || $Pedido->tipo_venda == 'pre_pago_producao_triangular') {
				if (
					$Pedido->cliente->inscricaoestadual === 'ISENTO' ||
					(intval($Pedido->cliente->indicadorinscricaoestadual) === 2 ||
						intval($Pedido->cliente->indicadorinscricaoestadual) === 9
					)
				) {
					$codigo_operacao = 'PEDIDOISENTO';
				} else {
					$codigo_operacao = 'PEDIDOVENDA';
				}
			} else if ($Pedido->tipo_venda === 'triangular' || $Pedido->tipo_venda == 'pronta_entrega_triangular' || $Pedido->tipo_venda == 'pedido_futuro_triangular' || $Pedido->tipo_venda == 'pre_pago_triangular') {
				$codigo_operacao = 'PEDTRIANGULAR';
			} else if ($Pedido->tipo_venda === 'isento') {
				$codigo_operacao = 'PEDIDOISENTO';
			} else if ($Pedido->tipo_venda === 'producao' || $Pedido->tipo_venda === 'producao_triangular' || $Pedido->tipo_venda === 'pre_pago_producao' || $Pedido->tipo_venda === 'pre_pago_producao_triangular') {
				$codigo_operacao = 'PEDIDOVENDA';
			}
		}

		return $codigo_operacao;
	}

	private function getMensagemNotaNasajon(PedidoPortal $Pedido, $operacao, $numero_pedido = '')
	{
		$mensagem = '';

		$condicao_pagamento = $Pedido->condicao_pagamento_detalhes;
		$forma_pagamento = $condicao_pagamento->forma_pagamento ?? '';
		$vendedor = $Pedido->usuario_detalhes->codigo_representante;
		$tipo_venda = $operacao;
		$telefone_transportador = $Pedido->detalhesTransportador->telefone;
		$pedido_id = $Pedido->id;
		$pedido_compra = $Pedido->no_pedido_compra;
		if (!empty($pedido_compra)) {
			$pedido_compra = mb_convert_encoding(utf8_decode($pedido_compra), "UTF-8", "Windows-1252");
		}
		$pedido_compra = str_replace("'", " ", $pedido_compra);

		if ($operacao == 'PEDIDORETVENDAFORA') {
			$mensagem = "Mercadorias serão entregues no endereço, Rua: Dr. Carlos Botelho,177 - Brás - São Paulo/SP - CEP: 03017-010\nNão incidência  do ICMS conforme resposta consulta 2.422/2013 e não incidência  de IPI conforme art. 38,IV do RIPI/2010";
		} else if (
			$operacao !== 'PEDIDOTRANSF' &&
			$operacao !== 'PEDIDOTRANSFSEMICMS'
		) {
			if (!empty($forma_pagamento)) {
				$descricao_pagamento = strtoupper(tirarAcentos($forma_pagamento->descricao));
			} else {
				$descricao_pagamento = '';
			}

			if (!empty($Pedido->itens_pedido->where('tem_ipi', true)->first()) && in_array($Pedido->estabelecimento, [3])) {
				$mensagem .= "redução de 35% conforme o Decreto nº 11.158/2022.\n";
			}

			$mensagem .= "" .
				"VND: {$vendedor}\n" .
				"PAGAMENTO EM {$descricao_pagamento} PED: {$numero_pedido} ({$tipo_venda}) Fone Transportadora: {$telefone_transportador}\n";
			if (!empty($Pedido->cliente->suframa_codigo) && in_array($Pedido->cliente->uf, ['RO', 'RR', 'AP', 'AC', 'AM'])) {
				$mensagem .= "Código Suframa: " . $Pedido->cliente->suframa_codigo . "\n";
			}

			/*
			if($Pedido->outlet != true){
				$mensagem .= "Só aceitaremos devoluções de mercadorias, no prazo máximo de 30 dias após o recebimento das mesmas.\nAs mercadorias deverão vir acompanhadas de nota fiscal de devolução.\n*FAVOR GUARDAR AS ETIQUETAS DAS EMBALAGENS, POIS SOMENTE COM ELAS SERÁ POSSÍVEL TROCAR MERCADORIAS*\n";
				$mensagem .= "Pedido Web: {$pedido_id}".(!empty($pedido_compra) ? " - Pedido de Compra: {$pedido_compra}" : "")."\n";
			}else{
				$mensagem .= "Produtos promocionais não passível devolução\n";
			}*/
			$mensagem .= "Só aceitaremos devoluções de mercadorias, no prazo máximo de 30 dias após o recebimento das mesmas.\nAs mercadorias deverão vir acompanhadas de nota fiscal de devolução.\n*FAVOR GUARDAR AS ETIQUETAS DAS EMBALAGENS, POIS SOMENTE COM ELAS SERÁ POSSÍVEL DEVOLUÇÃO DE MERCADORIAS*\n";
			$mensagem .= "Pedido Web: {$pedido_id}" . (!empty($pedido_compra) ? " - Pedido de Compra: {$pedido_compra}" : "") . "\n";

			if (in_array($Pedido->estabelecimento, [3, 4])) {
				$mensagem .= "Mercadoria com saída do MN Armazem Gerais Ltda localizado na EST. RIO MAGÉ 4791 - GALPÃO 03 ARMAZEM\n" .
					"CHAC.ARCAMPO - DUQUE DE CAXIAS - RJ - 25251-460, CNPJ: 97.544.848/0002-02 e IE: 86.696.517\n";
			}
			if (!empty($Pedido->transportadora_redespacho) && $Pedido->tipo_frete_redespacho !== 'P') {
				$mensagem .= "\n\nFRETE POR CONTA DO DESTINATÁRIO.\n";
			}
		} else {
			/**
			 * Mensagem de pedido de transferencia
			 */
			$mensagem = "" .
				"PED: {$numero_pedido} ({$tipo_venda})\n" .
				"Só aceitaremos devoluções de mercadorias, no prazo máximo de 20 dias após o recebimento das mesmas.\n" .
				"As mercadorias deverão vir acompanhadas de nota fiscal de devolução.\n" .
				"*FAVOR GUARDAR AS ETIQUETAS DAS EMBALAGENS, POIS SOMENTE COM ELAS SERÁ POSSÍVEL DEVOLUÇÃO DE MERCADORIAS*\n" .
				"Pedido Web: {$pedido_id}" . (!empty($pedido_compra) ? " - Pedido de Compra: {$pedido_compra}" : "") . "\n";
		}

		return $mensagem;
	}

	private function enviarEmail($pedido)
	{
		try {
			$pedidos = [];

			$EmailObj = new EmailController();

			if (!empty($pedido)) {

				$email_send = [];
				$nome_cliente = '';
				$cliente = $pedido->cliente;
				if (!empty($pedido->email_comprador)) {
					$email_send[] = $pedido->email_comprador;
				} elseif (!empty($cliente->email)) {
					$email_send[] = $cliente->email;
				}

				$email_send[] = $pedido->usuario_detalhes->email;

				if (!empty($pedido->nome_comprador)) {
					$nome_cliente = $pedido->nome_comprador;
				} elseif (!empty($cliente->email)) {
					$nome_cliente = $cliente->nome;
				}

				$variaveis = [
					'nome_cliente' => $nome_cliente,
					'numero_pedido' => $pedido->pedido_gerado,
					'link_pedido' => route('pedido_portal.detalhesDeslogado', ['hash' => encrypt(["pedido_id" => $pedido->id])])
				];

				if (count($email_send) > 0) {
					$EmailObj->sendEmailToken($pedido->estabelecimento, "pedido_aprovado", $email_send, $variaveis);
				}
			}
		} catch (\Exception $e) {
		}
	}

	private function enviarEmailEsperandoPagamento($pedido)
	{
		try {
			$pedidos = [];

			$EmailObj = new EmailController();

			if (!empty($pedido)) {
				if ($pedido->pedido_futuro == false) {
					$email_send = [];
					$nome_cliente = '';
					$cliente = $pedido->cliente;
					if (!empty($pedido->email_comprador)) {
						$email_send[] = $pedido->email_comprador;
					} elseif (!empty($cliente->email)) {
						$email_send[] = $cliente->email;
					}

					$email_send[] = $pedido->usuario_detalhes->email;

					if (!empty($pedido->nome_comprador)) {
						$nome_cliente = $pedido->nome_comprador;
					} elseif (!empty($cliente->email)) {
						$nome_cliente = $cliente->nome;
					}

					$variaveis = [
						'nome_cliente' => $nome_cliente,
						'numero_pedido' => $pedido->id,
						'link_pedido' => route('pedido_portal.detalhesDeslogado', ['hash' => encrypt(["pedido_id" => $pedido->id])]),
						'valor' => parserValor($pedido->valor_total_nota)
					];

					if (count($email_send) > 0) {
						$EmailObj->sendEmailToken('00', "dados_bancarios_usar_credito", $email_send, $variaveis);
					}
				}
			}
		} catch (\Exception $e) {
		}
	}

	private function filterAprovacaoProjeto($value, $users, $fields, $estabelecimentos)
	{
		$quantidade = 0;
		$valor_total = 0;

		if (!empty($fields['estabelecimento'])) {
			if (intval($fields['estabelecimento']) != 4 && intval($fields['estabelecimento']) != 5 && intval($fields['estabelecimento']) != 6) {
				$value['quantidade'] = $quantidade;
				$value['valor_total'] = $valor_total;
				return $value;
			}
		}

		$query_aprovacao_projeto = AprovacaoDeProjeto::select();
		$query_aprovacao_projeto->with(['projeto', 'nivelaprovacaoPreco', 'aprovador_credito', 'aprovador_preco']);
		if (strtolower(Auth::user()->tipo_usuario->nome) === "diretor" || strtolower(Auth::user()->tipo_usuario->nome) === "credito") {
		} else if (strpos(strtolower(Auth::user()->tipo_usuario->nome), "diretor") !== false ||  strpos(strtolower(Auth::user()->tipo_usuario->nome), "gerente") !== false) {
			$users = UserController::varreSubordinados(Auth::id());
			$query_aprovacao_projeto->whereHas('projeto', function ($query) use ($users) {
				$query->whereHas('detalhes_representante', function ($query) use ($users) {
					$query->whereIn('id', $users);
				});
			});
		} else if (strtolower(Auth::user()->tipo_usuario->nome) === "supervisor") {
			$users = UserController::varreSubordinados(Auth::user()->responsavel);
			$query_aprovacao_projeto->whereHas('projeto', function ($query) use ($users) {
				$query->whereHas('detalhes_representante', function ($query) use ($users) {
					$query->whereIn('id', $users);
				});
			});
		}

		$query_aprovacao_projeto->whereHas('projeto', function ($query) use ($fields) {
			if (isset($fields['cliente_nome']) && !empty($fields['cliente_nome'])) {
				$query->where(function ($query) use ($fields) {
					$cliente_busca = ClienteNasajon::select('cpf_cnpj')
						->where(DB::raw('CONCAT(TRIM(nome),\' - \', cpf_cnpj)'), 'ILIKE', $fields['cliente_nome']);
					if (intval($fields['estabelecimento']) == 4) {
						$cliente_busca->whereNotIn('uf', ['SP']);
					} else if (intval($fields['estabelecimento']) == 6 || intval($fields['estabelecimento']) == 5) {
						$cliente_busca->where('uf', 'SP');
					}
					$cliente_busca = $cliente_busca->get();
					$query->orWhereIn('cliente_cpf_cnpj', $cliente_busca->pluck('cpf_cnpj'));
				});
			} else if (!empty($fields['estabelecimento'])) {
				if (intval($fields['estabelecimento']) == 4 || intval($fields['estabelecimento']) == 6 || intval($fields['estabelecimento']) == 5) {
					$query->where(function ($query) use ($fields) {
						$cliente_busca = ClienteNasajon::select('cpf_cnpj');

						if (intval($fields['estabelecimento']) == 4) {
							$cliente_busca->whereNotIn('uf', ['SP']);
						} else if (intval($fields['estabelecimento']) == 6 || intval($fields['estabelecimento']) == 5) {
							$cliente_busca->where('uf', 'SP');
						}
						$cliente_busca = $cliente_busca->get();
						$query->orWhereIn('cliente_cpf_cnpj', $cliente_busca->pluck('cpf_cnpj'));
					});
				}
			}
		});
		if (!empty($fields['status'])) {
			if ($fields['status'] === 'credito') {
				$query_aprovacao_projeto->where('credito', true);
			}
			if ($fields['status'] === 'preco') {
				$query_aprovacao_projeto->where('preco', true);
			}
			if ($fields['status'] === 'retaguarda') {
				$query_aprovacao_projeto->where('retaguarda', true);
			}
		}

		$aprovacao_projetos = $query_aprovacao_projeto->get();

		foreach ($aprovacao_projetos as $aprovacao_projeto) {
			$mostrar_botao_aprovar = false;
			$mostrar_botao_reprovar = false;

			$aprovador = $aprovacao_projeto->nivelaprovacao->descricao;
			$nivel_usuario = Auth::user()->tipo_usuario->nivel;
			if (Auth::id() === 91) {
				$nivel_usuario = 1;
			}
			if ($aprovacao_projeto->credito === true) {
				if (empty($aprovacao_projeto->aprovacao_credito_user_id)) {
					if (empty($aprovacao_projeto->aprovacao_credito_user_id) && strtolower(Auth::user()->tipo_usuario->nome) === 'credito') {
						$mostrar_botao_aprovar = true;
						$mostrar_botao_reprovar = true;
					} else if (in_array($aprovacao_projeto->projeto->detalhes_representante->id, $users) || in_array(strtolower(Auth::user()->tipo_usuario->nome), ['diretor', 'diretor comercial'])) {
						$mostrar_botao_reprovar = true;
					}
				} else {
					if ($aprovacao_projeto->preco === true && empty($aprovacao_projeto->aprovacao_preco_user_id) && $nivel_usuario < $aprovacao_projeto->nivelaprovacaoPreco->id) {
						$mostrar_botao_aprovar = true;
						$mostrar_botao_reprovar = true;
					} else if (in_array($aprovacao_projeto->projeto->detalhes_representante->id, $users)) {
						$mostrar_botao_reprovar = true;
					}
				}
				if ($aprovacao_projeto->preco === true) {
					if (!empty($aprovacao_projeto->aprovacao_preco_user_id)) {
						$aprovador = '';
					} else {
						$aprovador = $aprovacao_projeto->nivelaprovacaoPreco->descricao;
					}
				} else {
					$aprovador = '';
				}

				if (empty($aprovacao_projeto->aprovacao_credito_user_id)) {
					$aprovador .= (!empty($aprovador) ? ' / ' : '') . 'crédito';
				}
			} else {
				if ($nivel_usuario < $aprovacao_projeto->nivelaprovacao['id']) {
					$mostrar_botao_aprovar = true;
					$mostrar_botao_reprovar = true;
				} else if (in_array($aprovacao_projeto->projeto->detalhes_representante->id, $users)) {
					$mostrar_botao_reprovar = true;
				}
			}

			if (strtolower(Auth::user()->tipo_usuario->nome) == 'administrador') {
				$mostrar_botao_aprovar = true;
				$mostrar_botao_reprovar = true;
			}
			$value[] = [
				'id' => $aprovacao_projeto->id,
				'estabelecimento' => "<div><div data-toggle='tooltip' data-html='true' title='' data-original-title='" . $estabelecimentos[$aprovacao_projeto->projeto->estabelecimento] . "''>" . $estabelecimentos[$aprovacao_projeto->projeto->estabelecimento] . "</div></div>",
				'status' => $aprovador,
				'cliente' => "<div><div data-toggle='tooltip' data-html='true' title='' data-original-title='" . $aprovacao_projeto->projeto->cliente->nome . "''>" . $aprovacao_projeto->projeto->cliente->nome . "</div></div>",
				'pedido' => $aprovacao_projeto->projeto_id,
				'projeto' => encrypt($aprovacao_projeto->projeto_id),
				'valor' => parserValor($aprovacao_projeto->projeto->valor_total_pedido),
				'condicao_pagamento' => "<div><div data-toggle='tooltip' data-html='true' title='' data-original-title='" . $aprovacao_projeto->projeto->condicoes_pagamento_web->descricao . "''>" . $aprovacao_projeto->projeto->condicoes_pagamento_web->descricao . "</div></div>",
				'tipo_pedido' => 'PR',
				'vendedor' => "<div><div data-toggle='tooltip' data-html='true' title='' data-original-title='" . $aprovacao_projeto->projeto->detalhes_representante->codigo_representante . " - " . $aprovacao_projeto->projeto->detalhes_representante->name . "'>" . $aprovacao_projeto->projeto->detalhes_representante->codigo_representante . " - " . $aprovacao_projeto->projeto->detalhes_representante->name . "</div></div>",
				'criterio_credito' => $aprovacao_projeto->credito ? (empty($aprovacao_projeto->aprovacao_credito_user_id) ? 'Não' : 'Aprovado') : 'Sim',
				'criterio_preco' => $aprovacao_projeto->preco ? (empty($aprovacao_projeto->aprovacao_preco_user_id) ? 'Não' : 'Aprovado') : 'Sim',
				'retaguarda' => $aprovacao_projeto->retaguarda ? 'Não' : 'Sim',
				'mostrar_botao_aprovar' => $mostrar_botao_aprovar,
				'mostrar_botao_reprovar' => $mostrar_botao_reprovar,
				'aprovador_credito' => empty($aprovacao_projeto->aprovador_credito->name) ? '' : $aprovacao_projeto->aprovador_credito->name,
				'aprovador_preco' => empty($aprovacao_projeto->aprovador_preco->name) ? '' : $aprovacao_projeto->aprovador_preco->name,
				'tipo' => 'projeto',
				'data' => parserData($aprovacao_projeto->projeto->data_entrada),
			];

			$quantidade++;
			$valor_total = $valor_total + $aprovacao_projeto->projeto->valor_total_pedido;
		}
		$value['quantidade'] = $quantidade;
		$value['valor_total'] = $valor_total;

		return $value;
	}

	public function retaguardaPedido(Request $request)
	{
		$fields = $request->only('id');

		$pedido = $fields['id'];
		$AprovacaoDePedidoObj = AprovacaoDePedido::where('pedido_id', $pedido)->first();
		$AprovacaoDePedidoObj->credito = false;
		$AprovacaoDePedidoObj->retaguarda = true;
		$AprovacaoDePedidoObj->save();

		return response()
			->json(
				[
					'status' => 'success',
					'message' => 'Pedido em retaguarda.',
					'error' => [],
					'response' => []
				],
				200
			);
	}

	public function pedidoAguardandoLiberacao()
	{
		$PedidoPortalObj = PedidoPortal::with(['condicao_pagamento_detalhes', 'cliente_conta_e_ordem', 'detalhesTransportador', 'detalhesTransportadorRedespacho', 'usuario_detalhes', 'itens_pedido', 'itens_pedido.info_produtoNasjon'])
			->where('status_pedido', 10)
			->where('data_previsao_entrega', '<=', date('Y-m-d'))
			->get();

		$PedidoPortalObj->each(function ($pedido) {
			if (!empty($pedido->detalhesTransportador)) {
				if (in_array($pedido->condicao_pagamento, $this->condicao_de_pagamento_usar_credito)) {
					$pedido->status_pedido = 9;
					$pedido->save();

					$pedidoUsarCreditoObj = PedidoUsarCredito::select()->where('pedido_id', $pedido->id)->first();
					if (empty($pedidoUsarCreditoObj)) {
						$pedidoUsarCreditoObj = new PedidoUsarCredito;
						$pedidoUsarCreditoObj->pedido_id = $pedido->id;
						$pedidoUsarCreditoObj->liberado = false;
						$pedidoUsarCreditoObj->data_bloqueio = Carbon::now();
						$pedidoUsarCreditoObj->created_by = Auth::id();
					} else {
						$pedidoUsarCreditoObj->liberado = false;
						$pedidoUsarCreditoObj->updated_by = Auth::id();
					}
					$pedidoUsarCreditoObj->save();

					$this->enviarEmailEsperandoPagamento($pedido);
				} else {
					$this->processaIntegracaoPedidoNasajon($pedido, []);
				}
			}
		});
	}

	public function pedidoAguardandoLiberacaoCliente()
	{
		$pedidoPortalVerificacaoObj = PedidoPortal::with(
			'clicksignDocumento'
		)
			->where('clicksign_documentos_id', 12)
			->get();

		foreach ($pedidoPortalVerificacaoObj as $pedido) {
			$query = ClicksignDocumento::select();
			$query->where('caminho_arquivo', 'ilike', '%/contratos_pedidos/' . $pedido->id . '/%');
			$result = $query->first();

			if (!empty($result)) {
				$pedido->clicksign_documentos_id = $result->id;
				$pedido->save();
			}
		}

		$pedidoPortalObj = PedidoPortal::with(
			'clicksignDocumento',
			'clicksignDocumento.clicksignSignatarioDocumento'
		)
			->whereNotNull('clicksign_documentos_id')
			->where('status_pedido', 12)
			->get();

		foreach ($pedidoPortalObj as $pedido) {
			if ($pedido->clicksignDocumento->status == 'closed') {
				$assinaturas = $pedido->clicksignDocumento->clicksignSignatarioDocumento->pluck('assinou_como')->count();
				if ($pedido->clicksignDocumento->clicksignSignatarioDocumento->where('assinou_como', '!=', null)->pluck('assinou_como')->count() == $assinaturas) {
					$request = new Request(['id' => $pedido->id]);
					$this->aprovaPedido($request);
				} else {
					$pedido->status_pedido = 7;
					$pedido->updated_by = 1;
					$pedido->save();
				}
			}
			if ($pedido->clicksignDocumento->status == 'canceled') {
				$pedido->status_pedido = 13;
				$pedido->delete();
				$pedido->save();
			}
		}
	}

	public function atualizarDataPrevisaoEntregaOriginal($pedido)
	{
		if (empty($pedido->data_previsao_entrega_original)) {
			$pedido->data_previsao_entrega_original = $pedido->data_previsao_entrega;
			$pedido->save();
		} else if ($pedido->data_previsao_entrega_original !== $pedido->data_previsao_entrega) {
			$pedido->data_previsao_entrega_ultima = $pedido->data_previsao_entrega;
			$pedido->save();
		}
	}


	private function checkNetrin($pedido)
	{
		$cliente_ok=true;
		
		if(env('APP_HOST') === 'producao' && !empty(env('APP_HOST'))){
			if(!in_array($pedido->cod_cliente, $this->codigo_grupo_textil_mn)){
				$clienteNetrinApiController  = new ClienteNetrinApiController();
				$transportador_ok = $clienteNetrinApiController->consultaTransportadorPedido($pedido,$this->codigo_cliente_balcao);
				$cliente_ok = $clienteNetrinApiController->consultaClientePedido($pedido,$this->codigo_cliente_balcao);
				if($transportador_ok ==false && $cliente_ok == true){
					$cliente_ok =false;
				}
			}
		}

		return $cliente_ok;
	}
}
